package main

import (
	"gno.land/r/gov/dao"
	valset "gno.land/r/sys/validators/v0"
)

func main(cur realm) {
	r := valset.NewValidatorProposalRequest(
		cross(cur),
		[]valset.ValoperChange{
			valset.NewValoperChange(address("g1zlrdlcs65d6yhschadhvlf3qnw9ruelh9rn6wn"), 1),
		},
		"Add 1 validator(s) to the valset",
		"Batch-add 1 operator(s) to the active valset with voting power 1.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}

package physics

// Wall is a straight barrier. Bounce overrides the field's restitution (0
// keeps it); Mark and Skin are for whoever draws it, except that only a
// bumper's skin kicks (Kicks).
type Wall struct {
	Seg    Segment
	Bounce float64 // 0 = use the field default
	Mark   rune
	Skin   string
	// Every > 0 times the wall within a stroke: it stands in substep i only
	// when (i+Tick+Phase) mod Every is below On.
	Every, On, Phase int
}

// There is the timing rule walls, zones and course pulses share (sign-safe
// mod, so a negative phase works): on at i when (i+phase) mod every is below
// on; every <= 0 is always there.
func There(i, every, on, phase int) bool {
	return every <= 0 || ((i+phase)%every+every)%every < on
}

// WithTick is the field with its clock moved on by tick substeps. It may
// return f itself (tick 0): do not mutate what it returns.
func WithTick(f *Field, tick int) *Field {
	if tick == 0 {
		return f
	}
	g := *f
	g.Tick = f.Tick + tick
	return &g
}

// Post is a round obstacle. Bounce is the contact's restitution, played at
// MaxBounce at most; above 1 with a bumper's skin (Kicks) it kicks the ball
// back faster than it came (at most MaxKick times).
type Post struct {
	Circle
	Bounce float64 // 0 = use the field default; played at MaxBounce at most; above 1 a bumper, if Kicks(Skin)
	Mark   rune
	Skin   string
}

// ZoneKind is what a zone does to a ball inside it.
type ZoneKind int

// The zone kinds, each named in its own line.
const (
	Surface ZoneKind = iota // Scale sets the rolling resistance (Rolling): sand holds, ice frees
	Slope                   // a hill: Vec, gravity along it, is added to velocity each substep
	Tunnel                  // the ball is moved to Vec, keeping its velocity
	Hazard                  // the ball goes back where the stroke was played from: water, a pit, the void
	// Loop is a tube's mouth (Min..Max): a ball heading in within 25° at
	// Scale or faster comes out at Vec, else it falls back or off the side.
	// The mouth must be at least MaxMove deep, or a fast ball steps over it.
	Loop
)

// LoopKeep is the share of its speed a ball keeps once round a loop.
const LoopKeep = 0.8

// Zone is an area of the board that changes how the ball moves: the rectangle
// Min..Max, or the ellipse inside it (Round), or a polygon (Poly), or all of it
// but a polygon (Outside). Vec and Scale mean what the kind says.
type Zone struct {
	Kind     ZoneKind
	Min, Max Vec2
	Vec      Vec2    // Slope: acceleration (G·sin θ downhill). Tunnel: destination. Loop: where it comes down. Hazard: unused.
	Scale    float64 // Surface: its rolling resistance (Rolling). Loop: the speed to go round.
	Mark     rune
	Skin     string
	// Round makes the zone the ellipse inscribed in Min..Max.
	Round bool
	// Poly (3 points or more) makes the zone that polygon, within Min..Max;
	// Outside makes it everything in Min..Max but the polygon.
	Poly    []Vec2
	Outside bool
	// Every, On, Phase time the zone within a stroke, as for a Wall.
	Every, On, Phase int
	// Air makes a Slope moving air: it pushes the ball but is no hill, and
	// hides none under it. Capped air never speeds the ball up.
	Air, Capped bool
}

// Contains says whether p is in the zone, by its shape.
func (z Zone) Contains(p Vec2) bool { return z.contains(p) }

// contains is Contains through a pointer: a Zone is too big to copy per move.
func (z *Zone) contains(p Vec2) bool {
	if p.X < z.Min.X || p.X >= z.Max.X || p.Y < z.Min.Y || p.Y >= z.Max.Y {
		return false
	}
	if len(z.Poly) >= 3 {
		return inPoly(z.Poly, p) != z.Outside
	}
	if !z.Round {
		return true
	}
	hx, hy := (z.Max.X-z.Min.X)/2, (z.Max.Y-z.Min.Y)/2
	dx, dy := (p.X-z.Min.X-hx)/hx, (p.Y-z.Min.Y-hy)/hy
	return dx*dx+dy*dy < 1
}

// Field is everything a ball rolls through: walls, posts and zones.
type Field struct {
	Walls    []Wall
	Posts    []Post
	Zones    []Zone
	Friction float64 // the green's rolling resistance, as Rolling maps it: 0.87 is Crr 0.224
	Bounce   float64 // default restitution of barriers
	// Radius of the ball (0 plays it as a point).
	Radius float64
	// Tick is where the stroke starts on the clock of timed walls and zones.
	Tick int
	// Cap, above 0 and under MaxWork, replaces MaxWork for this stroke.
	Cap int
	// prep is the walls' offsets, worked out once (Prepare).
	prep []float64
}

// String is the kind's name as clients read it: "surface", "slope", ...
func (k ZoneKind) String() string {
	switch k {
	case Surface:
		return "surface"
	case Slope:
		return "slope"
	case Tunnel:
		return "tunnel"
	case Hazard:
		return "hazard"
	case Loop:
		return "loop"
	}
	return "unknown"
}

// inPoly is the even-odd point-in-polygon test.
func inPoly(pts []Vec2, p Vec2) bool {
	in := false
	for i := range pts {
		a, b := pts[i], pts[(i+1)%len(pts)]
		if (a.Y > p.Y) != (b.Y > p.Y) && p.X < a.X+(p.Y-a.Y)*(b.X-a.X)/(b.Y-a.Y) {
			in = !in
		}
	}
	return in
}

package physics

import "math"

// Segment is a straight barrier from A to B.
type Segment struct{ A, B Vec2 }

// Normal is the unit left-normal of the segment.
func (s Segment) Normal() Vec2 {
	d := s.B.Sub(s.A)
	l := d.Len()
	if l == 0 {
		return Vec2{}
	}
	return Vec2{-d.Y / l, d.X / l}
}

// Crosses reports whether the motion p0->p1 crosses the segment, without
// working out the normal (and its square root).
func (s Segment) Crosses(p0, p1 Vec2) bool {
	_, _, ok := s.hitN(p0, p1, Vec2{})
	return ok
}

// hitN reports where the motion p0->p1 crosses the segment: the travel
// fraction in [0,1] and the given normal (precomputed, to save a square
// root per test), turned to face the motion.
func (s Segment) hitN(p0, p1, normal Vec2) (float64, Vec2, bool) {
	d := p1.Sub(p0)
	e := s.B.Sub(s.A)
	den := d.X*e.Y - d.Y*e.X
	if math.Abs(den) < 1e-12 {
		return 0, Vec2{}, false // parallel
	}
	f := s.A.Sub(p0)
	t := (f.X*e.Y - f.Y*e.X) / den // along the motion
	u := (f.X*d.Y - f.Y*d.X) / den // along the barrier
	if t < 0 || t > 1 || u < 0 || u > 1 {
		return 0, Vec2{}, false
	}
	n := normal
	if d.Dot(n) > 0 {
		n = n.Scale(-1)
	}
	return t, n, true
}

// Circle is a round barrier: a post, a bumper, the rim of a pond.
type Circle struct {
	C Vec2
	R float64
}

// hit is the swept point-vs-circle test, adding rootWork to *w per square
// root. A ball that starts inside reports no hit: a post never traps a ball.
func (c Circle) hit(p0, p1 Vec2, w *int) (float64, Vec2, bool) {
	d := p1.Sub(p0)
	a := d.Dot(d)
	if a < 1e-12 {
		return 0, Vec2{}, false
	}
	m := p0.Sub(c.C)
	if m.Dot(m) < c.R*c.R {
		return 0, Vec2{}, false // started inside
	}
	b := 2 * m.Dot(d)
	k := m.Dot(m) - c.R*c.R
	disc := b*b - 4*a*k
	if disc < 0 {
		return 0, Vec2{}, false
	}
	*w += rootWork
	t := (-b - math.Sqrt(disc)) / (2 * a)
	if t < 0 || t > 1 {
		return 0, Vec2{}, false
	}
	n := p0.Add(d.Scale(t)).Sub(c.C)
	*w += rootWork
	l := n.Len()
	if l == 0 {
		return 0, Vec2{}, false
	}
	return t, n.Scale(1 / l), true
}

package physics

import (
	"math"
	"strings"
)

// G is gravity, in board units per substep squared: a hill's Vec is G·sin θ.
const G = 1.0

// The calibration of Rolling, fitted by least squares to the course's
// strokes: keep = min((Friction+keepBonus)·Scale, maxKeep), then
// Crr = ((1−keep)·RollSpeed + RollDrag/Scale) / G.
const (
	RollSpeed = 1.8
	RollDrag  = 0.08
	keepBonus = 0.05
	maxKeep   = 0.98
)

// Rolling is the rolling-resistance coefficient Crr of a green of the given
// Friction under a Surface of the given Scale (1 is plain grass). A Scale of
// 0 or less is an infinite Crr: the ball stays where it is.
func Rolling(friction, scale float64) float64 {
	if !(scale > 0) {
		return math.Inf(1)
	}
	keep := (friction + keepBonus) * scale
	if keep > maxKeep {
		keep = maxKeep
	}
	return ((1-keep)*RollSpeed + RollDrag/scale) / G
}

// The contact rules for walls and posts.
const (
	// WallFriction is the Coulomb µ between the ball and a wall or post:
	// the tangential impulse is at most µ times the normal one.
	WallFriction = 0.05
	// TangentMass caps the tangential impulse, per unit mass and speed:
	// 2/7 is what stops a solid ball's contact point from slipping.
	TangentMass = 2.0 / 7
	// RestSpeed is the speed into a surface, per substep, under which a
	// contact is resting: no restitution, no bounce counted. At least what
	// the steepest hill adds in a substep, so a ball a hill presses into a
	// rail slides along it instead of jittering.
	RestSpeed = 0.35
	// MaxBounce is the most restitution a passive piece plays: a Bounce
	// above it is played at it.
	MaxBounce = 0.75
	// MaxKick is the most restitution a bumper (a Bounce above 1 on a skin
	// that Kicks) plays, and the most course.Decode accepts. The ball stays
	// under SpeedCap.
	MaxKick = 1.5
)

// The flight rules: a ball takes off over a hill's crest (its uphill edge)
// when v² > G·CrestRadius, v its speed up the hill, flies a ballistic arc and
// lands at the height it took off from.
const (
	// CrestRadius is the radius of a hill's lip, in board units: a ball
	// needs sqrt(G·CrestRadius), 0.71 per substep, to take off.
	CrestRadius = 0.5
	// MinRamp is the gentlest hill (|Vec|) that launches.
	MinRamp = 0.12
	// GroundBounce is the restitution of the ground when a ball lands.
	GroundBounce = 0.4
	// LandFriction is the Coulomb µ between a landing ball and the ground.
	LandFriction = 0.3
	// HopSpeed is the vertical speed, per substep, under which a landing
	// ball stays down.
	HopSpeed = 0.25
	// MaxSin is the steepest grade a hill plays, sin θ (about 72°), so tan θ
	// and a flight stay bounded; course.Decode holds |Vec| to G·MaxSin.
	MaxSin = 0.95
)

// MaxRollOn caps the substeps a ball may roll on past its stroke's own while
// a slope keeps it moving or it is still in the air.
const MaxRollOn = 120

// pinCheck and pinMove: a ball rolling on that moves less than pinMove in
// pinCheck substeps is pinned, and stops.
const (
	pinCheck = 8
	pinMove  = 0.1
)

// MaxWork caps what one stroke may cost, whatever the field, in work units
// of about a thousand gas each (Shot.Work): a stroke that reaches it ends
// where the ball is. A Field's Cap lowers it for one stroke.
const MaxWork = 1000000

// The work weights, in units, measured on the GnoVM with probes that add one
// kind of piece at a time, so that a unit costs at most 0.87K gas.
const (
	substepWork  = 700
	moveWork     = 15
	barWork      = 12
	broadWork    = 18
	wallTestWork = 130
	postTestWork = 50
	zoneWork     = 20
	inWork       = 25
	edgeWork     = 14
	roundWork    = 12
	pushWork     = 50
	rootWork     = 200
	unstickWork  = 5
)

// MaxWorkStep is the most a stroke's Work passes its limit (MaxWork, or a
// lower Cap) by on a Decode-limited field: the most between two checks.
// Golf holds a shot to its limit plus this (shotBound).
const MaxWorkStep = 225000

// limit is the work the stroke may cost: MaxWork, or the field's Cap under it.
func (f *Field) limit() int {
	if f.Cap > 0 && f.Cap < MaxWork {
		return f.Cap
	}
	return MaxWork
}

// maxHits is the most contacts one move resolves (a corner meets two).
const maxHits = 4

// Shot is everything a stroke did: where the ball was at every substep, and
// how many walls and posts it met. A renderer replays Path and never
// simulates; two consecutive points far apart are a tunnel, not a line to
// interpolate.
type Shot struct {
	Path    []Vec2
	Bounces int
	// Air marks the path points where the ball is off the ground (no zone
	// acts, no cup takes it). Same length as Path.
	Air []bool
	// Cause says, per path point, what most acted on the ball in the substep
	// that ended there: 'b' a bounce, 's' a hill, 'w' wind or a gust, 'i' a
	// slippery surface, '-' nothing but friction. Same length as Path.
	Cause []byte
	why   byte // this substep's cause so far
	// Work is what the stroke cost, in MaxWork's units.
	Work int
	// start is where the stroke was played from, where a hazard sends it.
	start Vec2
}

func (s *Shot) add(p Vec2, air bool) {
	s.Path = append(s.Path, p)
	s.Air = append(s.Air, air)
	s.Cause = append(s.Cause, '-')
}

// mark records c as this substep's cause if it outranks what is there.
func (s *Shot) mark(c byte) {
	if strings.IndexByte(causes, c) > strings.IndexByte(causes, s.why) {
		s.why = c
	}
}

// causes is the Cause letters, weakest first.
const causes = "-iwsb"

// The loop's mouth: a ball heading in within 45° (loopIn, cos 45°) enters,
// one more than 25° off straight (loopStraight, cos 25°) is set down loopDrop
// in front, loopFront outside the mouth; one too slow rolls back out at
// loopBack of its speed.
const (
	loopIn       = 0.7071
	loopStraight = 0.9063
	loopFront    = 0.01
	loopDrop     = 1.5
	loopBack     = 0.5
)

// Rest is where the ball stopped.
func (s Shot) Rest() Vec2 {
	if len(s.Path) == 0 {
		return Vec2{}
	}
	return s.Path[len(s.Path)-1]
}

// MaxMove is the longest single move inside a substep. Zones are sampled once
// per move, so a zone must be at least this deep along the way a ball crosses
// it, or a fast ball can step over it unseen.
const MaxMove = 1.5

// SpeedCap is the fastest a ball may go, in board units per substep, held at
// the start of every substep and after every bounce: it bounds a substep to
// 6 moves, even between two bumpers or down a slope on ice.
const SpeedCap = 8

// Step rolls a ball through the field until it comes to rest or runs out of
// substeps (and past them while a slope keeps it rolling or it is still in
// the air, see MaxRollOn). With a Radius, the ball meets walls and posts with
// its edge. Cost is O(moves * (walls + posts + zones)), paid on every shot.
func (f *Field) Step(pos, vel Vec2, substeps int) Shot {
	out := Shot{Path: make([]Vec2, 0, substeps+2), Air: make([]bool, 0, substeps+2), start: pos}
	out.add(pos, false)
	air := 0.0 // substeps left in the air; 0 on the ground
	vz := 0.0  // the vertical speed the ball took off (or bounced) with
	hop := 0.0 // a landing's rebound, up again once the zones under it are met

	// wall offsets once per shot (or per hole, Prepare), never per move
	offs := f.offsets()
	bars := f.timedBars()
	slopes := f.groundSlopes()

	extra := 0 // substeps rolled on past the stroke's (MaxRollOn)
	// the hill being climbed, and how far up it the climb began
	var ramp *hill
	rampFrom, from := 0.0, pos
	// rolling on, a ball a slope pins against a wall only jitters: it stops
	// once it has not got anywhere in pinCheck substeps
	base, anchor := substeps, pos
	// the rolling deceleration the ball meets, per substep: where it starts,
	// then the last substep's
	drag := f.resistance(slopes, pos, f.Tick, &out.Work)
	limit := f.limit()
	for i := 0; i < substeps; i++ {
		tick := i + f.Tick
		if out.Work > limit {
			break // spent: the ball stops where the last substep left it
		}
		if i >= base && (i-base)%pinCheck == 0 {
			if i > base && air <= 0 && pos.Sub(anchor).Len() < pinMove {
				break
			}
			anchor = pos
		}
		if i == substeps-1 && f.rollsOn(extra, air, 0, slopes, pos, &out.Work) { // hop 0: the check at the substep's end sees a pending one
			substeps++
			extra++
		}
		// A timed bar that comes back (or stands, on the first substep) on
		// the ball pushes it out (UnstickIn). Every bar is pushed before the
		// work is checked, so a stroke never ends inside one.
		out.Work += barWork * len(bars)
		for _, j := range bars {
			w := &f.Walls[j]
			if There(tick, w.Every, w.On, w.Phase) && (i == 0 || !There(tick-1, w.Every, w.On, w.Phase)) {
				pos = UnstickIn(pos, f.Walls[j:j+4], nil, f.Radius, f.Walls)
				out.Work += 4 * unstickWork * len(f.Walls)
			}
		}
		spent := out.Work > limit
		if spent {
			if pos != out.Rest() {
				out.add(pos, false)
			}
			break
		}
		// moves of at most MaxMove, so a fast ball meets every zone and wall
		// it crosses; the path still gets one point per substep
		speed := vel.Len()
		if speed > SpeedCap {
			vel, speed = vel.Scale(SpeedCap/speed), SpeedCap
		}
		// Rolling resistance as two half-kicks around the moves (velocity
		// Verlet, so a ball rolls v²/2a), the first at the last substep's
		// deceleration. It never reverses the ball: it stops it.
		if air <= 0 && hop <= 0 {
			if dv := drag / 2; speed > dv {
				vel, speed = vel.Scale((speed-dv)/speed), speed-dv
			} else {
				vel, speed = Vec2{}, 0
				// at rest where no hill can move it, it stays (no creeping)
				if !f.rolls(slopes, pos, tick, &out.Work) {
					if pos != out.Rest() {
						out.add(pos, false) // where a timed bar put it
					}
					break
				}
			}
		}
		n := int(speed/MaxMove) + 1
		dt := 1 / float64(n)
		roll := 0.0 // the rolling deceleration, summed over the moves on the ground
		out.why = '-'
		for k := 0; k < n; k++ {
			if out.Work > limit {
				spent = true // the stroke has cost all it may: it ends here
				break
			}
			out.Work += moveWork
			// in the air no zone acts: the ball flies over water, sand, a
			// tunnel's mouth
			var up *hill
			if air <= 0 {
				// grass unless a zone under this move says otherwise
				surface := 1.0
				var under *hill
				if f.zonesAt(&pos, &vel, &surface, &under, slopes, n, tick, &out) {
					return out
				}
				if surface > 1 {
					out.mark('i')
				}
				if hop > 0 {
					// a landing's rebound, once the ground had its say
					// (water under it still catches it)
					vz, air, hop = hop, 2*hop/G, 0
				} else {
					c := 1.0
					if under != nil {
						c = under.cos
					}
					roll += Rolling(f.Friction, surface) * G * c
				}
				up = under
				if up != nil && vel.Dot(up.z.Vec) >= 0 {
					up = nil // on the hill, but not climbing it
				}
				if up != ramp {
					// a new climb counts from where the ball came onto the hill
					ramp = up
					if up != nil {
						rampFrom = up.along(from)
					}
				}
			}
			from = pos

			// contact to contact: a hit spends the rest of the move from there
			hit, left := false, 1.0
			for h := 0; h < maxHits && left > 0; h++ {
				if out.Work > limit {
					break // spent: the ball stops where it is
				}
				move := vel.Scale(left * dt)
				next := pos.Add(move)
				best, normal, bounce, ok := f.sweep(offs, pos, next, move, tick, &out)
				if !ok {
					pos = next
					break
				}
				const skin = 1e-6
				pos = pos.Add(move.Scale(best)).Add(normal.Scale(skin))
				var impact bool
				vel, impact = contact(vel, normal, bounce)
				out.Work += rootWork // contact's
				if vel.LenCmp(SpeedCap) > 0 {
					out.Work += rootWork
					vel = vel.Scale(SpeedCap / vel.Len()) // two bumpers facing each other
				}
				if impact {
					out.Bounces++
					out.mark('b')
				}
				hit = true
				left *= 1 - best
			}
			if air > 0 {
				if air -= dt; air <= 0 {
					// landing: restitution up, Coulomb friction along
					air = 0
					j := (1 + GroundBounce) * vz
					if l := vel.Len(); l > 0 {
						dv := LandFriction * j
						if s := TangentMass * l; dv > s {
							dv = s
						}
						vel = vel.Scale((l - dv) / l)
					}
					if vz *= GroundBounce; vz > HopSpeed {
						hop = vz
					}
				}
			} else if up != nil && !hit && !f.climbs(slopes, pos, vel, tick, &out.Work) && up.overTheTop(from, pos, rampFrom, &out.Work) {
				// over the crest faster than its curve holds: take off
				if vu := vel.Dot(up.u); vu > 0 && vu*vu > G*CrestRadius {
					vz = vu * up.tan
					air = 2 * vz / G
				}
			}
		}
		out.add(pos, air > 0)
		out.Cause[len(out.Cause)-1] = out.why
		if spent {
			break
		}
		// airborne, a landing to bounce, or onto a hill by now: go on too
		if i == substeps-1 && f.rollsOn(extra, air, hop, slopes, pos, &out.Work) {
			substeps++
			extra++
		}
		out.Work += substepWork
		if air > 0 || hop > 0 {
			drag = 0
			continue // no rolling resistance off the ground
		}

		// the second half-kick, at the moves' mean deceleration on the ground
		drag = roll * dt
		l := vel.Len()
		if dv := drag / 2; l > dv {
			vel = vel.Scale((l - dv) / l)
			continue
		}
		vel = Vec2{}
		// on a hill steeper than its resistance, it rolls back next substep
		if f.rolls(slopes, pos, tick+1, &out.Work) {
			continue
		}
		break
	}

	// a ball at rest is on the ground, whatever was left of its flight
	out.Air[len(out.Air)-1] = false
	// a ball at rest in water or a tunnel's mouth is resolved now
	var still Vec2
	surface := 1.0
	var under *hill
	if f.zonesAt(&pos, &still, &surface, &under, slopes, 1, substeps+f.Tick, &out) {
		return out
	}
	// a ball at rest in a timed hazard or tunnel meets it whatever the tick:
	// it would be there when it next comes on
	for j := range f.Zones {
		z := &f.Zones[j]
		out.Work += zoneWork
		if z.Every <= 0 || z.On <= 0 || (z.Kind != Hazard && z.Kind != Tunnel) || !z.in(pos, &out.Work) {
			continue
		}
		if z.Kind == Hazard {
			out.add(out.start, false)
			return out
		}
		pos = z.Vec
		out.add(pos, false)
	}
	return out
}

// contact applies the contact impulse to vel against a surface of unit
// normal n (toward the ball): restitution along n, Coulomb friction along
// the surface. It reports an impact (not a resting contact).
func contact(vel, n Vec2, bounce float64) (Vec2, bool) {
	vn := vel.Dot(n)
	if !(vn < 0) {
		return vel, false // not moving into it
	}
	e := bounce
	if e > 1 {
		if e > MaxKick {
			e = MaxKick
		}
	} else if e > MaxBounce {
		e = MaxBounce
	}
	impact := -vn >= RestSpeed
	if !impact {
		e = 0
	}
	jn := -(1 + e) * vn // the normal impulse, per unit mass
	vt := vel.Sub(n.Scale(vn))
	if lt := vt.Len(); lt > 0 {
		jt := WallFriction * jn
		if s := TangentMass * lt; jt > s {
			jt = s
		}
		vt = vt.Scale((lt - jt) / lt)
	}
	return vt.Add(n.Scale(-e * vn)), impact
}

// sweep is the first wall or post the move pos→next meets: how far along it
// (0 to 1), the surface's normal there (toward the ball), and its bounce.
func (f *Field) sweep(offs []offset, pos, next, move Vec2, tick int, out *Shot) (float64, Vec2, float64, bool) {
	const skin = 1e-6
	out.Work += broadWork * (len(offs) + len(f.Posts))
	// broad phase: skip a wall or post whose box the move's box misses
	lo, hi := pos, next
	if lo.X > hi.X {
		lo.X, hi.X = hi.X, lo.X
	}
	if lo.Y > hi.Y {
		lo.Y, hi.Y = hi.Y, lo.Y
	}
	best, normal, restitution, hit := 1.0, Vec2{}, f.Bounce, false
	for j := range offs {
		o := &offs[j]
		if o.hi.X < lo.X || o.lo.X > hi.X || o.hi.Y < lo.Y || o.lo.Y > hi.Y {
			continue
		}
		if !There(tick, o.every, o.on, o.phase) {
			continue // a timed wall that is not there this substep
		}
		out.Work += wallTestWork
		side := pos.Sub(o.a).Dot(o.n)
		seg, sn, facing := o.plus, o.pn, o.n
		if side < 0 {
			seg, sn, facing = o.minus, o.mn, o.n.Scale(-1)
		}
		// Already within the radius (a corner, a wall that moved onto the
		// ball): the offset line is behind it, so meet the wall now.
		if f.Radius > 0 {
			d := side
			if d < 0 {
				d = -d
			}
			if d <= f.Radius+skin/2 {
				along := Vec2{o.n.Y, -o.n.X}
				u := pos.Sub(o.a).Dot(along) // along the wall, from A toward B
				if u >= 0 && u <= o.length {
					if move.Dot(facing) < 0 {
						best, normal, hit = 0, facing, true
						restitution = o.bounce
					}
					continue
				}
				// past an end, the ball meets the end point, not the face
				// (whose normal points across a corner's next wall):
				// touching it, push back from it; else sweep it as a cap
				end := o.a
				if u > o.length {
					end = o.a.Add(along.Scale(o.length))
				}
				rv := pos.Sub(end)
				out.Work += rootWork
				if l := rv.Len(); l > 0 && l <= f.Radius+skin/2 {
					if nrm := rv.Scale(1 / l); move.Dot(nrm) < 0 {
						best, normal, hit = 0, nrm, true
						restitution = o.bounce
					}
				} else if t, nn, ok := (Circle{C: end, R: f.Radius}).hit(pos, next, &out.Work); ok && t < best {
					best, normal, hit = t, nn, true
					restitution = o.bounce
				}
				continue
			}
		}
		if t, nn, ok := seg.hitN(pos, next, sn); ok && t < best {
			best, normal, hit = t, nn, true
			restitution = o.bounce
		}
		// the offset lines' square ends leave a gap at an acute corner's
		// tip: sweep both ends as round caps too (inside the square ones)
		if f.Radius > 0 && o.length > 0 {
			along := Vec2{o.n.Y, -o.n.X}
			for _, end := range [2]Vec2{o.a, o.a.Add(along.Scale(o.length))} {
				if t, nn, ok := (Circle{C: end, R: f.Radius}).hit(pos, next, &out.Work); ok && t < best {
					best, normal, hit = t, nn, true
					restitution = o.bounce
				}
			}
		}
	}
	for j := range f.Posts {
		p := &f.Posts[j]
		c := p.Circle
		c.R += f.Radius
		if reach := c.R + boxPad; c.C.X+reach < lo.X || c.C.X-reach > hi.X || c.C.Y+reach < lo.Y || c.C.Y-reach > hi.Y {
			continue
		}
		out.Work += postTestWork
		if t, nn, ok := c.hit(pos, next, &out.Work); ok && t < best {
			best, normal, hit = t, nn, true
			restitution = bounceOf(p.Bounce, f.Bounce, p.Skin)
		}
	}
	return best, normal, restitution, hit
}

// zonesAt applies the zones the ball is in, and reports whether one ended
// the shot. The first ground Slope there is the hill (left in *under);
// moving air pushes on top of it.
func (f *Field) zonesAt(pos, vel *Vec2, surface *float64, under **hill, slopes []hill, n, tick int, out *Shot) bool {
	*under = nil
	hk := 0 // the next hill of slopes, in field order
	for j := range f.Zones {
		z := &f.Zones[j]
		ground := z.Kind == Slope && !z.Air
		var h *hill
		if ground {
			if hk < len(slopes) {
				h = &slopes[hk]
			}
			hk++
		}
		out.Work += zoneWork
		if !There(tick, z.Every, z.On, z.Phase) || !z.in(*pos, &out.Work) {
			continue
		}
		switch z.Kind {
		case Surface:
			*surface = z.Scale // the surface under this move (the last listed wins)
		case Slope:
			if ground {
				if *under != nil || h == nil {
					continue // already on a hill: the first one is the ground
				}
				*under = h
				out.mark('s')
				out.Work += pushWork
				*vel = vel.Add(z.Vec.Scale(1 / float64(n)))
				continue
			}
			out.mark('w')
			out.Work += pushWork
			wind := z.Capped
			v2 := 0.0
			if wind {
				v2 = vel.Dot(*vel)
			}
			*vel = vel.Add(z.Vec.Scale(1 / float64(n)))
			// capped wind never speeds the ball up (on ice it would keep a
			// ball drifting); squared first, rooted only when it did
			if l2 := vel.Dot(*vel); wind && l2 > v2 {
				out.Work += 2 * rootWork // two roots
				if v0, l := math.Sqrt(v2), math.Sqrt(l2); l > v0 {
					if v0 == 0 {
						*vel = Vec2{}
					} else {
						*vel = vel.Scale(v0 / l)
					}
				}
			}
		case Tunnel:
			*pos = z.Vec
			out.add(*pos, false)
		case Hazard:
			out.add(out.start, false) // back where the stroke was played from
			return true
		case Loop:
			// decided at once: the ball is put out of the mouth, so it never
			// has to remember being inside
			axis, sign := Vec2{1, 0}, 1.0
			mid := z.Min.Add(z.Max).Scale(0.5)
			if math.Abs(z.Vec.Y-mid.Y) > math.Abs(z.Vec.X-mid.X) {
				axis = Vec2{0, 1}
			}
			if z.Vec.Dot(axis) < mid.Dot(axis) {
				sign = -1
			}
			in := axis.Scale(sign) // the way into the loop
			out.Work += rootWork
			sp := vel.Len()
			if vel.Dot(in) <= sp*loopIn {
				continue // not heading into the mouth: it rolls across
			}
			// more than 25° off straight
			slanted := vel.Dot(in) <= sp*loopStraight
			front := z.Min.Dot(axis) - loopFront
			if sign < 0 {
				front = z.Max.Dot(axis) + loopFront
			}
			side := pos.Sub(axis.Scale(pos.Dot(axis)))
			switch {
			case slanted:
				// off the side of the track: down in front of the mouth, still
				*pos = mid.Sub(axis.Scale(mid.Dot(axis))).Add(axis.Scale(front - sign*loopDrop))
				out.add(*pos, false)
				return true
			case sp >= z.Scale:
				*pos = z.Vec
				*vel = in.Scale(sp * LoopKeep)
			default:
				*pos = side.Add(axis.Scale(front))
				*vel = vel.Scale(-loopBack)
			}
			out.add(*pos, false)
		}
	}
	return false
}

// bounceOf is the Bounce a piece plays: its own, or the field's (def), and
// above 1 only for a bumper (Kicks); any other plays MaxBounce.
func bounceOf(b, def float64, skin string) float64 {
	if b = orDefault(b, def); b > 1 && !Kicks(skin) {
		return MaxBounce
	}
	return b
}

// Kicks reports whether a piece of this skin may kick the ball back faster
// than it came (a Bounce above 1). Every other piece is passive.
func Kicks(skin string) bool {
	return strings.Contains(skin, "bumper") || strings.Contains(skin, "pinball") || strings.Contains(skin, "mushroom")
}

func orDefault(v, def float64) float64 {
	if v == 0 {
		return def
	}
	return v
}

// hill is a ground slope: its steepness g = |Vec| (G·sin θ), cos θ, tan θ,
// u the unit uphill, and its crest, the zone's edge u mostly points at.
type hill struct {
	z        *Zone
	g        float64
	cos, tan float64
	u        Vec2
	onX      bool    // the crest is an edge across X (u mostly along X)
	crest    float64 // where it is, on that axis
	foot     float64 // the opposite edge, where a climb starts
	depth    float64 // foot to crest
	upward   float64 // +1 when uphill runs toward +X (or +Y), -1 the other way
}

func newHill(z *Zone) hill {
	h := hill{z: z, g: z.Vec.Len(), cos: 1}
	if h.g == 0 {
		return h // decor: never climbed
	}
	sin := h.g / G
	if sin > MaxSin {
		sin = MaxSin
	}
	h.cos = math.Sqrt(1 - sin*sin)
	h.tan = sin / h.cos
	h.u = z.Vec.Scale(-1 / h.g)
	h.onX = math.Abs(h.u.X) >= math.Abs(h.u.Y)
	lo, hi, dir := z.Min.Y, z.Max.Y, h.u.Y
	if h.onX {
		lo, hi, dir = z.Min.X, z.Max.X, h.u.X
	}
	h.crest, h.foot, h.upward = hi, lo, 1
	if dir < 0 {
		h.crest, h.foot, h.upward = lo, hi, -1
	}
	h.depth = hi - lo
	return h
}

// along is how far up the hill p is from its foot (0 at the foot or below).
func (h *hill) along(p Vec2) float64 {
	c := p.Y
	if h.onX {
		c = p.X
	}
	if d := (c - h.foot) * h.upward; d > 0 {
		return d
	}
	return 0
}

// JumpRun is the share of a hill's depth a ball must have climbed to take off
// at its top: one that only clipped the hill near its crest has not ridden it.
const JumpRun = 0.5

// overTheTop reports whether the move a→b left the hill through its crest
// (not a side or its foot) after climbing at least JumpRun of it from
// rampFrom. A hill no steeper than MinRamp launches nothing.
func (h *hill) overTheTop(a, b Vec2, rampFrom float64, w *int) bool {
	if h.g <= MinRamp || h.z.in(b, w) {
		return false
	}
	ac, bc, oa, ob := a.Y, b.Y, a.X, b.X
	lo, hi := h.z.Min.X, h.z.Max.X
	if h.onX {
		ac, bc, oa, ob = a.X, b.X, a.Y, b.Y
		lo, hi = h.z.Min.Y, h.z.Max.Y
	}
	if (bc-h.crest)*h.upward < 0 || ac == bc {
		return false // it did not get past the crest's line
	}
	// where the move crosses the crest's line must be on the crest
	if o := oa + (h.crest-ac)/(bc-ac)*(ob-oa); o < lo || o >= hi {
		return false
	}
	return h.depth-rampFrom >= JumpRun*h.depth
}

// groundSlopes is the field's hills, in field order, measured once per shot.
func (f *Field) groundSlopes() []hill {
	var out []hill
	for j := range f.Zones {
		// air is no hill; a timed hill counts while it is there
		if z := &f.Zones[j]; z.Kind == Slope && !z.Air {
			out = append(out, newHill(z))
		}
	}
	return out
}

// ground is the hill under the ball at tick, as zonesAt has it; nil off
// every hill. A tick below 0 asks for the untimed hills only.
func (f *Field) ground(slopes []hill, pos Vec2, tick int, w *int) *hill {
	for j := range slopes {
		s := &slopes[j]
		*w += zoneWork
		if (tick < 0 && s.z.Every > 0) || (tick >= 0 && !There(tick, s.z.Every, s.z.On, s.z.Phase)) {
			continue
		}
		if s.z.in(pos, w) {
			return s
		}
	}
	return nil
}

// climbs reports whether the ball is moving up the hill under it.
func (f *Field) climbs(slopes []hill, pos, vel Vec2, tick int, w *int) bool {
	h := f.ground(slopes, pos, tick, w)
	return h != nil && vel.Dot(h.z.Vec) < 0
}

// resistance is the rolling deceleration Crr·G·cos θ at pos at tick. A tick
// below 0 asks for the untimed zones only.
func (f *Field) resistance(slopes []hill, pos Vec2, tick int, w *int) float64 {
	t := tick
	if t < 0 {
		t = 0
	}
	surface := 1.0
	for j := range f.Zones {
		*w += zoneWork
		if z := &f.Zones[j]; z.Kind == Surface && (tick >= 0 || z.Every <= 0) && There(t, z.Every, z.On, z.Phase) && z.in(pos, w) {
			surface = z.Scale
		}
	}
	c := 1.0
	if h := f.ground(slopes, pos, tick, w); h != nil {
		c = h.cos
	}
	return Rolling(f.Friction, surface) * G * c
}

// rollsOn says whether a stroke on its last substep goes on for one more:
// in the air, a landing to bounce (hop), or on a hill that rolls it.
func (f *Field) rollsOn(extra int, air, hop float64, slopes []hill, pos Vec2, w *int) bool {
	return extra < MaxRollOn && (air > 0 || hop > 0 || f.rolls(slopes, pos, -1, w))
}

// rolls reports whether a ball at rest at pos rolls away at tick (G·sin θ
// above Crr·G·cos θ). A tick below 0 asks for the untimed hills only: a
// rocking plank would roll a ball on for all MaxRollOn substeps.
func (f *Field) rolls(slopes []hill, pos Vec2, tick int, w *int) bool {
	h := f.ground(slopes, pos, tick, w)
	return h != nil && h.g > f.resistance(slopes, pos, tick, w)
}

// in is contains, adding what the test costs to *w (zoneWork is the
// caller's); every polygon edge is charged as if it straddled p.
func (z *Zone) in(p Vec2, w *int) bool {
	if p.X < z.Min.X || p.X >= z.Max.X || p.Y < z.Min.Y || p.Y >= z.Max.Y {
		return false
	}
	*w += inWork
	if len(z.Poly) >= 3 {
		*w += edgeWork * len(z.Poly)
	} else if z.Round {
		*w += roundWork
	}
	return z.contains(p)
}

// Package physics is a 2D rolling-ball engine: it answers where a ball goes,
// never what that means.
//
// +X is right, +Y is down, 1.0 is one board unit, angles are in radians.
// Deterministic: float64 only, no map iteration, no clock, no randomness.
//
// Inputs must be finite: a NaN or an infinity gives no panic and no endless
// loop, but no meaningful answer either. Callers check them.
package physics

import "math"

// Vec2 is a point or a displacement on the board, in board units.
type Vec2 struct{ X, Y float64 }

// V is Vec2{x, y}, short so a course's coordinates read as coordinates.
func V(x, y float64) Vec2 { return Vec2{X: x, Y: y} }

// Add is a+b.
func (a Vec2) Add(b Vec2) Vec2 { return Vec2{a.X + b.X, a.Y + b.Y} }

// Sub is a-b.
func (a Vec2) Sub(b Vec2) Vec2 { return Vec2{a.X - b.X, a.Y - b.Y} }

// Scale is a times s.
func (a Vec2) Scale(s float64) Vec2 { return Vec2{a.X * s, a.Y * s} }

// Dot is the dot product of a and b.
func (a Vec2) Dot(b Vec2) float64 { return a.X*b.X + a.Y*b.Y }

// Len is the length of a.
func (a Vec2) Len() float64 { return math.Sqrt(a.Dot(a)) }

// LenCmp compares a.Len() with r: -1 shorter, 0 equal, 1 longer, exactly as
// comparing a.Len() would. It takes the costly square root only within 1e-12
// of r², where a.Dot(a) alone could round the other way. For board-scale r.
func (a Vec2) LenCmp(r float64) int {
	d2, r2 := a.Dot(a), r*r
	switch {
	case r < 0 || d2 > r2*(1+1e-12):
		return 1
	case d2 < r2*(1-1e-12):
		return -1
	}
	l := math.Sqrt(d2)
	if l < r {
		return -1
	}
	if l > r {
		return 1
	}
	return 0
}

// FromPolar builds a vector of length r pointing at angle (radians).
func FromPolar(angle, r float64) Vec2 {
	return Vec2{r * math.Cos(angle), r * math.Sin(angle)}
}

package physics

import "math"

// offset is what Step needs of a wall: its two offset lines (where the
// ball's centre meets it), their normals, the wall's start, normal and
// length, its bounce and timing, and its broad-phase box.
type offset struct {
	plus, minus      Segment
	pn, mn           Vec2 // plus.Normal(), minus.Normal()
	a, n             Vec2
	length, bounce   float64
	every, on, phase int
	lo, hi           Vec2
}

// unstickGap is how far clear of a piece UnstickIn sets a ball down.
const unstickGap = 0.02

// boxPad grows every broad-phase box: more than the half skin of Step's near
// test, and far more than rounding.
const boxPad = 1e-6

// lines works out a wall's offset lines for a ball of radius r: the segment
// pushed r to each side and lengthened by r at each end. Same bits as Normal
// and that push, with 3 square roots instead of 8.
func lines(s Segment, r float64, o *offset) {
	d := s.B.Sub(s.A)
	l := d.Len()
	o.a, o.length = s.A, l
	if l == 0 {
		o.plus, o.minus, o.n, o.pn, o.mn = s, s, Vec2{}, Vec2{}, Vec2{}
	} else {
		n := Vec2{-d.Y / l, d.X / l}
		toward := func(p Vec2) Segment {
			m := n
			if p.Sub(s.A).Dot(m) < 0 {
				m = m.Scale(-1)
			}
			e, off := d.Scale(r/l), m.Scale(r)
			return Segment{A: s.A.Sub(e).Add(off), B: s.B.Add(e).Add(off)}
		}
		o.n = n
		o.plus, o.minus = toward(s.A.Add(n)), toward(s.A.Sub(n))
		o.pn, o.mn = o.plus.Normal(), o.minus.Normal()
	}
	o.lo, o.hi = o.plus.A, o.plus.A
	for _, p := range []Vec2{o.plus.B, o.minus.A, o.minus.B} {
		if p.X < o.lo.X {
			o.lo.X = p.X
		} else if p.X > o.hi.X {
			o.hi.X = p.X
		}
		if p.Y < o.lo.Y {
			o.lo.Y = p.Y
		} else if p.Y > o.hi.Y {
			o.hi.Y = p.Y
		}
	}
	o.lo, o.hi = o.lo.Sub(Vec2{boxPad, boxPad}), o.hi.Add(Vec2{boxPad, boxPad})
}

// stride is the floats per wall in Field.prep: the wall's ends (to know the
// entry is still that wall's), then plus, minus, pn, mn, n, length, lo, hi.
const stride = 23

// Prepare works out the field's wall offsets once, for every shot to reuse.
// Call it once the walls are where they stay: Step works out again any wall
// that no longer matches its entry.
func Prepare(f *Field) {
	p := make([]float64, 1, 1+stride*len(f.Walls))
	p[0] = f.Radius
	var o offset
	for j := range f.Walls {
		s := f.Walls[j].Seg
		lines(s, f.Radius, &o)
		p = appendPrep(p, s, &o)
	}
	f.prep = p
}

func appendPrep(p []float64, s Segment, o *offset) []float64 {
	return append(p, s.A.X, s.A.Y, s.B.X, s.B.Y,
		o.plus.A.X, o.plus.A.Y, o.plus.B.X, o.plus.B.Y,
		o.minus.A.X, o.minus.A.Y, o.minus.B.X, o.minus.B.Y,
		o.pn.X, o.pn.Y, o.mn.X, o.mn.Y, o.n.X, o.n.Y, o.length,
		o.lo.X, o.lo.Y, o.hi.X, o.hi.Y)
}

// Lengths is the three square roots Prepare takes for a wall and a ball of
// radius r: the wall's length, then its plus and minus offset lines'.
func Lengths(s Segment, r float64) (l, lp, lm float64) {
	var o offset
	lines(s, r, &o)
	return o.length, o.plus.B.Sub(o.plus.A).Len(), o.minus.B.Sub(o.minus.A).Len()
}

// PrepareWith is Prepare with each wall's Lengths given, three per wall in
// wall order: the same prep, bit for bit, when they are the walls' own. It
// does not check them; whoever stored them must have. With the wrong count
// it is Prepare.
func PrepareWith(f *Field, lens []float64) {
	if len(lens) != 3*len(f.Walls) {
		Prepare(f)
		return
	}
	p := make([]float64, 1, 1+stride*len(f.Walls))
	p[0] = f.Radius
	var o offset
	for j := range f.Walls {
		s := f.Walls[j].Seg
		linesWith(s, f.Radius, &o, lens[3*j], lens[3*j+1], lens[3*j+2])
		p = appendPrep(p, s, &o)
	}
	f.prep = p
}

// Prepared is a copy of the field's prep, to compare bit for bit.
func Prepared(f *Field) []float64 {
	out := make([]float64, len(f.prep))
	copy(out, f.prep)
	return out
}

// linesWith is lines with its square roots given (Lengths): the same
// operations in the same order, so the same bits, written out by hand to
// save lines' calls. Keep the two in step.
func linesWith(s Segment, r float64, o *offset, l, lp, lm float64) {
	dx, dy := s.B.X-s.A.X, s.B.Y-s.A.Y
	o.a, o.length = s.A, l
	if l == 0 {
		o.plus, o.minus, o.n, o.pn, o.mn = s, s, Vec2{}, Vec2{}, Vec2{}
	} else {
		nx, ny := -dy/l, dx/l
		q := r / l
		ex, ey := dx*q, dy*q
		o.n = Vec2{nx, ny}
		o.plus = towardWith(s, nx, ny, ex, ey, r, s.A.X+nx, s.A.Y+ny)
		o.minus = towardWith(s, nx, ny, ex, ey, r, s.A.X-nx, s.A.Y-ny)
		o.pn = normalWith(o.plus, lp)
		o.mn = normalWith(o.minus, lm)
	}
	lo, hi := o.plus.A, o.plus.A
	if p := o.plus.B; p.X < lo.X {
		lo.X = p.X
	} else if p.X > hi.X {
		hi.X = p.X
	}
	if p := o.plus.B; p.Y < lo.Y {
		lo.Y = p.Y
	} else if p.Y > hi.Y {
		hi.Y = p.Y
	}
	if p := o.minus.A; p.X < lo.X {
		lo.X = p.X
	} else if p.X > hi.X {
		hi.X = p.X
	}
	if p := o.minus.A; p.Y < lo.Y {
		lo.Y = p.Y
	} else if p.Y > hi.Y {
		hi.Y = p.Y
	}
	if p := o.minus.B; p.X < lo.X {
		lo.X = p.X
	} else if p.X > hi.X {
		hi.X = p.X
	}
	if p := o.minus.B; p.Y < lo.Y {
		lo.Y = p.Y
	} else if p.Y > hi.Y {
		hi.Y = p.Y
	}
	o.lo, o.hi = Vec2{lo.X - boxPad, lo.Y - boxPad}, Vec2{hi.X + boxPad, hi.Y + boxPad}
}

// towardWith is lines' toward: the offset line on (px, py)'s side.
func towardWith(s Segment, nx, ny, ex, ey, r, px, py float64) Segment {
	mx, my := nx, ny
	if (px-s.A.X)*mx+(py-s.A.Y)*my < 0 {
		mx, my = mx*-1, my*-1
	}
	ox, oy := mx*r, my*r
	return Segment{A: Vec2{(s.A.X - ex) + ox, (s.A.Y - ey) + oy}, B: Vec2{(s.B.X + ex) + ox, (s.B.Y + ey) + oy}}
}

// normalWith is Segment.Normal with the length given.
func normalWith(s Segment, l float64) Vec2 {
	if l == 0 {
		return Vec2{}
	}
	return Vec2{-(s.B.Y - s.A.Y) / l, (s.B.X - s.A.X) / l}
}

// offsets is every wall's offset for this shot: from the prep where it still
// matches the wall, worked out otherwise.
func (f *Field) offsets() []offset {
	offs := make([]offset, len(f.Walls))
	p := f.prep
	if len(p) == 0 || p[0] != f.Radius {
		p = nil
	}
	for j := range f.Walls {
		w := &f.Walls[j]
		o := &offs[j]
		if k := 1 + j*stride; k+stride <= len(p) && p[k] == w.Seg.A.X && p[k+1] == w.Seg.A.Y && p[k+2] == w.Seg.B.X && p[k+3] == w.Seg.B.Y {
			o.plus = Segment{Vec2{p[k+4], p[k+5]}, Vec2{p[k+6], p[k+7]}}
			o.minus = Segment{Vec2{p[k+8], p[k+9]}, Vec2{p[k+10], p[k+11]}}
			o.pn, o.mn, o.n = Vec2{p[k+12], p[k+13]}, Vec2{p[k+14], p[k+15]}, Vec2{p[k+16], p[k+17]}
			o.a, o.length = w.Seg.A, p[k+18]
			o.lo, o.hi = Vec2{p[k+19], p[k+20]}, Vec2{p[k+21], p[k+22]}
		} else {
			lines(w.Seg, f.Radius, o)
		}
		o.bounce = bounceOf(w.Bounce, f.Bounce, w.Skin)
		o.every, o.on, o.phase = w.Every, w.On, w.Phase
	}
	return offs
}

// timedBars is where each timed bar starts in f.Walls: four timed walls in a
// row, one timing, closing on themselves (build.Timed(build.Bar(…))).
func (f *Field) timedBars() []int {
	var out []int
	ws := f.Walls
	for j := 0; j+3 < len(ws); j++ {
		a := &ws[j]
		if a.Every <= 0 {
			continue
		}
		closed := true
		for k := 0; k < 4; k++ {
			w, next := &ws[j+k], &ws[j+(k+1)%4]
			if w.Every != a.Every || w.On != a.On || w.Phase != a.Phase || w.Seg.B != next.Seg.A {
				closed = false
				break
			}
		}
		if closed {
			out = append(out, j)
			j += 3
		}
	}
	return out
}

// UnstickIn moves a ball of radius r out of pieces that appeared on top of
// it. walls are read in bars of four (build.Bar): a ball inside one leaves
// through the nearest side it can; one closer than r to a bar or a post is
// pushed off it. No push crosses an untimed wall of stays: out of a bar the
// ball tries the next side, else it stays; any other such push is not made.
func UnstickIn(ball Vec2, walls []Wall, posts []Post, r float64, stays []Wall) Vec2 {
	for i := 0; i+3 < len(walls); i += 4 {
		q := walls[i : i+4]
		c := q[0].Seg.A.Add(q[1].Seg.A).Add(q[2].Seg.A).Add(q[3].Seg.A).Scale(0.25)
		inside := true
		for _, w := range q {
			if side(w.Seg, ball) != side(w.Seg, c) {
				inside = false
			}
		}
		if inside {
			// nearest side first, along its outward normal
			var tried [4]bool
			for range q {
				k, best, bestD := -1, Vec2{}, math.Inf(1)
				for j, w := range q {
					if p := w.Seg.Closest(ball); !tried[j] {
						if d := p.Sub(ball).Len(); d < bestD {
							k, best, bestD = j, p, d
						}
					}
				}
				if k < 0 {
					break // a NaN ball: no side is nearest
				}
				tried[k] = true
				n := q[k].Seg.Normal()
				if n.Dot(best.Sub(c)) < 0 {
					n = n.Scale(-1)
				}
				if to := best.Add(n.Scale(r + unstickGap)); !crossesAny(stays, ball, to) {
					ball = to
					break
				}
			}
			continue
		}
		best, bestD := Vec2{}, math.Inf(1)
		for _, w := range q {
			p := w.Seg.Closest(ball)
			if d := p.Sub(ball).Len(); d < bestD {
				best, bestD = p, d
			}
		}
		if bestD < r {
			out := ball.Sub(best)
			if l := out.Len(); l > 0 {
				if to := best.Add(out.Scale((r + unstickGap) / l)); !crossesAny(stays, ball, to) {
					ball = to
				}
			}
		}
	}
	for _, p := range posts {
		d := ball.Sub(p.C)
		if l := d.Len(); l < p.R+r {
			if l == 0 {
				d, l = Vec2{X: 1}, 1
			}
			if to := p.C.Add(d.Scale((p.R + r + unstickGap) / l)); !crossesAny(stays, ball, to) {
				ball = to
			}
		}
	}
	return ball
}

// crossesAny reports whether the move a->b crosses one of the untimed walls.
func crossesAny(walls []Wall, a, b Vec2) bool {
	for j := range walls {
		if walls[j].Every <= 0 && walls[j].Seg.Crosses(a, b) {
			return true
		}
	}
	return false
}

func side(s Segment, p Vec2) bool {
	return s.B.Sub(s.A).X*(p.Y-s.A.Y)-s.B.Sub(s.A).Y*(p.X-s.A.X) > 0
}

// Closest is the point of the segment nearest p.
func (s Segment) Closest(p Vec2) Vec2 {
	d := s.B.Sub(s.A)
	l := d.Dot(d)
	if l == 0 {
		return s.A
	}
	t := p.Sub(s.A).Dot(d) / l
	if t < 0 {
		t = 0
	} else if t > 1 {
		t = 1
	}
	return s.A.Add(d.Scale(t))
}

// Package course is what golf and a hole agree on: a hole as data (Simple,
// GG1), its weather, and how a stroke is launched and drops.
package course

import (
	"math"
	"strconv"

	"gno.land/p/nym-alexiscolin000/gnogolf/physics"
)

// BoardW and BoardH are the board author.Fit gives a hole declared without W
// and H, in board units (nothing deployed reads them: Decode holds W and H to
// 1..MaxBoard).
const BoardW, BoardH = 32, 16

// WearW and WearH are the wear grid, stretched over any board: 128 counters.
const WearW, WearH = 16, 8

// MaxBoard is the longest side a board may have: it bounds the text board
// and the flood a client runs.
const MaxBoard = 96

// WearIndexOn maps a position on a w x h board to its wear cell, clamped.
func WearIndexOn(p physics.Vec2, w, h int) int {
	x := int(p.X * WearW / float64(w))
	y := int(p.Y * WearH / float64(h))
	if x < 0 {
		x = 0
	}
	if x >= WearW {
		x = WearW - 1
	}
	if y < 0 {
		y = 0
	}
	if y >= WearH {
		y = WearH - 1
	}
	return y*WearW + x
}

// Pulse is pieces that come and go: present on the strokes where
// (stroke+Phase) % Every < On, a timed wall's rule (physics.There) applied per
// stroke. The clock is the stroke number in the player's own round (0 is the
// first shot), never shared between players: previewing shot N and
// committing it meet the same course.
type Pulse struct {
	Every, On, Phase int
	Walls            []physics.Wall
	Posts            []physics.Post
	Zones            []physics.Zone
}

// The weather kinds. Each but Clear is also the skin of its whole-board zones.
const (
	Clear = ""      // Clear is no weather at all
	Wind  = "wind"  // Wind is a Slope: a steady push, Vec per substep
	Rain  = "rain"  // Rain is a Surface a little quicker than dry grass
	Fog   = "fog"   // Fog is a Surface of scale 1: it only hides the far end
	Storm = "storm" // Storm is rain and wind in gusts, and lightning to look at
	Snow  = "snow"  // Snow is a Surface a little slower
)

// chance is one kind of weather in a climate, out of 100.
type chance struct {
	percent int
	kind    string
}

// climates is each world's chance of each kind, out of 100; a world not
// listed has the garden's. Unexported so nothing can change it.
var climates = map[string][]chance{
	"garden":   {{55, Clear}, {20, Wind}, {15, Rain}, {10, Fog}},
	"island":   {{50, Clear}, {25, Wind}, {15, Rain}, {10, Storm}},
	"town":     {{50, Clear}, {20, Rain}, {15, Fog}, {15, Wind}},
	"mountain": {{40, Clear}, {25, Snow}, {20, Wind}, {15, Fog}},
}

// The weather's strengths.
const (
	// WindMin is the weakest wind, per substep.
	WindMin = 0.08
	// WindMax is the strongest wind, per substep.
	WindMax = 0.15
	// RainScale is how much quicker the green is in the rain: a touch, not
	// ice (much more and every board turns to pinball).
	RainScale = 1.025
	// WetIce is how much quicker again the rain makes ice.
	WetIce = 1.06
	// SnowScale is how much slower the green is in the snow.
	SnowScale = 0.9
)

// Forecast is one hole's weather for one period. Whole-board zones lie under
// the hole's own; the rest (puddles, wet ice) lie over it.
type Forecast struct {
	Period int64
	Kind   string
	Wind   physics.Vec2
	Zones  []physics.Zone
	// Work is what drawing it cost, in physics.MaxWork's units (about a
	// thousand gas); golf counts it in a commit's budget.
	Work int
}

// hash is 64-bit FNV-1a: small, deterministic, the same on every validator.
func hash(s string) uint64 {
	h := uint64(14695981039346656037)
	for i := 0; i < len(s); i++ {
		h ^= uint64(s[i])
		h *= 1099511628211
	}
	return h
}

// ForecastFor is the weather of hole id (in world) for a period: a hash of
// the two looked up in the world's climate. Nobody picks it.
func ForecastFor(id, world string, h *Simple, period int64) Forecast {
	seed := hash(id + "#" + strconv.FormatInt(period, 10))
	table, ok := climates[world]
	if !ok {
		table = climates["garden"]
	}
	roll, kind := int(seed%100), Clear
	for _, c := range table {
		if roll < c.percent {
			kind = c.kind
			break
		}
		roll -= c.percent
	}
	f := Forecast{Period: period, Kind: kind, Work: forecastWork}
	f.Wind, f.Zones = weatherFor(kind, h, seed, &f.Work)
	return f
}

// rng is a tiny deterministic generator from a seed (Knuth's LCG).
type rng struct{ s uint64 }

func (r *rng) next() uint64 {
	r.s = r.s*6364136223846793005 + 1442695040888963407
	return r.s >> 11
}

func (r *rng) unit() float64 { return float64(r.next()%1000000) / 1000000 }

// WeatherFor is the wind and zones of one kind of weather on a hole, drawn
// from seed: the wind's side and strength, where the rain leaves its puddles.
func WeatherFor(kind string, h *Simple, seed uint64) (physics.Vec2, []physics.Zone) {
	var work int
	return weatherFor(kind, h, seed, &work)
}

// weatherFor is WeatherFor, adding what it cost to *work (see wet).
func weatherFor(kind string, h *Simple, seed uint64, work *int) (physics.Vec2, []physics.Zone) {
	W, H := float64(h.W), float64(h.H)
	all := func(k physics.ZoneKind, skin string, scale float64, vec physics.Vec2) physics.Zone {
		// the wind is air, and never speeds the ball up
		air := k == physics.Slope
		return physics.Zone{Kind: k, Min: physics.V(0, 0), Max: physics.V(W, H), Scale: scale, Vec: vec, Skin: skin, Air: air, Capped: air}
	}
	r := &rng{s: seed}
	blow := func() physics.Vec2 {
		s := WindMin + r.unit()*(WindMax-WindMin)
		if h.Shelter > 0 && s > h.Shelter {
			s = h.Shelter
		}
		return physics.FromPolar(r.unit()*2*math.Pi, s)
	}
	switch kind {
	case Wind:
		v := blow()
		return v, []physics.Zone{all(physics.Slope, Wind, 0, v)}
	case Rain:
		return physics.Vec2{}, wet(h, r, []physics.Zone{all(physics.Surface, Rain, RainScale, physics.Vec2{})}, work)
	case Storm:
		// rain, and the wind in two alternating gusts
		*work += stormWork
		v := blow()
		a, s := math.Atan2(v.Y, v.X), v.Len()
		g1, g2 := all(physics.Slope, Wind, 0, physics.FromPolar(a+gustTurn, s)), all(physics.Slope, Wind, 0, physics.FromPolar(a-gustTurn, s))
		g1.Every, g1.On, g1.Phase = gustEvery, gustEvery/2, 0
		g2.Every, g2.On, g2.Phase = gustEvery, gustEvery/2, gustEvery/2
		zs := []physics.Zone{all(physics.Surface, Storm, 1, physics.Vec2{}), all(physics.Surface, Rain, RainScale, physics.Vec2{}), g1, g2}
		return v, wet(h, r, zs, work)
	case Fog:
		return physics.Vec2{}, []physics.Zone{all(physics.Surface, Fog, 1, physics.Vec2{})}
	case Snow:
		return physics.Vec2{}, []physics.Zone{all(physics.Surface, Snow, SnowScale, physics.Vec2{})}
	}
	return physics.Vec2{}, nil
}

// A storm's gusts turn gustTurn radians (about 40°) off its wind, one way
// then the other, each for half of gustEvery substeps.
const (
	gustTurn  = 0.7
	gustEvery = 6
)

// Where rain leaves its puddles: minPuddles plus up to morePuddles-1 more,
// in at most puddleTries tries; each puddleR plus up to puddleGrow wide,
// puddleAspect as deep, and puddleScale as quick as the grass, kept
// puddleGap clear of the one before.
const (
	minPuddles   = 2
	morePuddles  = 3
	puddleTries  = 60
	puddleR      = 1.1
	puddleGrow   = 0.7
	puddleAspect = 0.8
	puddleScale  = 0.6
	puddleGap    = 0.5
)

// The work of a forecast, in physics.MaxWork's units, measured on GnoVM gas:
// any forecast, a storm's gusts, a puddle try, and in it each post, zone,
// polygon edge and fixed wall dryLand tests, and each zone wet checks for ice.
const (
	forecastWork = 3000 // drawing any forecast, before the rain's tries
	stormWork    = 5000 // a storm's gusts, on top
	tryWork      = 35
	dryPostWork  = 22
	dryZoneWork  = 20
	dryEdgeWork  = 16
	dryWallWork  = 100
	iceWork      = 5
)

// WorstForecastWork bounds the Work of h's forecast in any period and world:
// a storm's, whose puddle tries all fail, each after dryLand has tested every
// piece (a try that fails sooner costs less, and one that places a puddle
// ends them sooner). Golf refuses a hole whose worst forecast leaves a commit
// no room for its heaviest shot.
func WorstForecastWork(h *Simple) int {
	f := h.Field()
	try := tryWork + dryPostWork*len(f.Posts)
	for _, z := range f.Zones {
		try += dryZoneTest(z)
	}
	for _, wl := range f.Walls {
		if wl.Every <= 0 {
			try += dryWallWork
		}
	}
	return forecastWork + stormWork + iceWork*len(f.Zones) + puddleTries*try
}

// dryZoneTest is the work of dryLand's test of one zone: its polygon's edges
// too for any zone but plain ground (Contains, at its dearest).
func dryZoneTest(z physics.Zone) int {
	if (z.Kind != physics.Surface && z.Kind != physics.Slope) || (z.Kind == physics.Surface && z.Skin != "") {
		return dryZoneWork + dryEdgeWork*len(z.Poly)
	}
	return dryZoneWork
}

// wet adds what rain leaves on a hole: its ice quicker still, and two to four
// puddles on the lane, clear of the kerb, the pieces, the tee and the cup.
// What it costs goes in *work.
func wet(h *Simple, r *rng, zs []physics.Zone, work *int) []physics.Zone {
	f := h.Field()
	*work += iceWork * len(f.Zones)
	for _, z := range f.Zones {
		if z.Kind == physics.Surface && z.Skin == "ice" {
			z.Scale *= WetIce
			zs = append(zs, z)
		}
	}
	want, placed := minPuddles+int(r.next()%morePuddles), []physics.Zone{}
	for try := 0; try < puddleTries && len(placed) < want; try++ {
		c := physics.V(r.unit()*float64(h.W), r.unit()*float64(h.H))
		rad := puddleR + r.unit()*puddleGrow
		*work += tryWork
		if !dryLand(h, c, rad, work) {
			continue
		}
		clash := false
		for _, p := range placed {
			if p.Min.Add(p.Max).Scale(0.5).Sub(c).LenCmp(p.Max.X-p.Min.X+puddleGap) < 0 {
				clash = true
			}
		}
		if clash {
			continue
		}
		placed = append(placed, physics.Zone{Kind: physics.Surface, Min: c.Sub(physics.V(rad, rad*puddleAspect)), Max: c.Add(physics.V(rad, rad*puddleAspect)), Scale: puddleScale, Round: true, Skin: "puddle"})
	}
	return append(zs, placed...)
}

// dryLand says whether a puddle of radius rad can lie at c: inside the lane's
// outline (even-odd over the fixed walls, a ray to a far point at a slant no
// grid wall lies along), off any zone but plain ground, dryGap from any piece
// and dryTee from tee and cup. Cheap tests first, no square roots: on a lane
// hole every try fails.
func dryLand(h *Simple, c physics.Vec2, rad float64, work *int) bool {
	f := h.Field()
	if c.Sub(h.Start()).LenCmp(rad+dryTee) < 0 || c.Sub(h.Cup()).LenCmp(rad+dryTee) < 0 {
		return false
	}
	for _, p := range f.Posts {
		*work += dryPostWork
		if p.C.Sub(c).LenCmp(p.R+rad+dryGap) < 0 {
			return false
		}
	}
	for _, z := range f.Zones {
		*work += dryZoneTest(z)
		if z.Kind != physics.Surface && z.Kind != physics.Slope && z.Contains(c) {
			return false
		}
		if z.Kind == physics.Surface && z.Skin != "" && z.Contains(c) {
			return false // not on the sand or the ice: a puddle is on the green
		}
	}
	far, in := c.Add(physics.V(farX, farY)), false
	for _, wl := range f.Walls {
		if wl.Every > 0 {
			continue
		}
		*work += dryWallWork
		if c.Sub(wl.Seg.Closest(c)).LenCmp(rad+dryGap) < 0 {
			return false
		}
		if wl.Seg.Crosses(c, far) {
			in = !in
		}
	}
	return in
}

const (
	dryTee     = 2
	dryGap     = 0.3
	farX, farY = 1e4, 37
)

// WithWeather lays weather over a field: the sky's whole-board zones go under
// its own (the sand stays sand in the rain), puddles and wet ice over them.
// It may return f itself: do not mutate what it returns.
func WithWeather(f *physics.Field, weather []physics.Zone) *physics.Field {
	if len(weather) == 0 {
		return f
	}
	under, over := []physics.Zone{}, []physics.Zone{}
	for _, z := range weather {
		switch z.Skin {
		case Wind, Rain, Fog, Storm, Snow:
			under = append(under, z)
		default:
			over = append(over, z)
		}
	}
	g := *f
	g.Zones = append(append(append(make([]physics.Zone, 0, len(f.Zones)+len(weather)), under...), f.Zones...), over...)
	return &g
}

// WithZones is the field with zones put first (a puddle over the sand is the
// puddle). It may return f itself: do not mutate what it returns.
func WithZones(f *physics.Field, zones []physics.Zone) *physics.Field {
	if len(zones) == 0 {
		return f
	}
	g := *f
	g.Zones = append(append(make([]physics.Zone, 0, len(f.Zones)+len(zones)), zones...), f.Zones...)
	return &g
}

// WithExtras is the field plus one stroke's pieces, the hole's own left as
// is. It may return f itself: do not mutate what it returns.
func WithExtras(f *physics.Field, walls []physics.Wall, posts []physics.Post) *physics.Field {
	if len(walls) == 0 && len(posts) == 0 {
		return f
	}
	g := *f
	g.Walls = append(append(make([]physics.Wall, 0, len(f.Walls)+len(walls)), f.Walls...), walls...)
	g.Posts = append(append(make([]physics.Post, 0, len(f.Posts)+len(posts)), f.Posts...), posts...)
	return &g
}

// Simple is a hole: its geometry, what Decode gives golf. Fields and methods
// pair up (Strokes/Par, Tee/Start, Pin/Cup, Course/Field) because a field and
// a method cannot share a name.
type Simple struct {
	W, H      int // the board, 1 to MaxBoard a side (Decode holds data to it, author.Fit sets it)
	Title     string
	Strokes   int // par: the strokes a good round takes (0 means 3)
	Tee, Pin  physics.Vec2
	Course    *physics.Field
	Pulses    []Pulse // pieces that come and go with the stroke number
	Substeps  int
	CupRadius float64
	// World is the hole's world (1 to MaxWorld letters a-z, as Decode holds
	// it); Order is its place there, 0 to MaxOrder (a course hole 1 or more).
	World string
	Order float64
	// Shelter caps the wind the hole is played in (0: the world's own).
	Shelter float64
}

// ExtraZones is the zones the hole's pulses lay down at a stroke.
func (h *Simple) ExtraZones(stroke int) []physics.Zone {
	var zs []physics.Zone
	for _, p := range h.Pulses {
		if physics.There(stroke, p.Every, p.On, p.Phase) {
			zs = append(zs, p.Zones...)
		}
	}
	return zs
}

// Varies says whether the hole has pulses: pieces that come and go.
func (h *Simple) Varies() bool { return len(h.Pulses) > 0 }

// Extras is the walls and posts the hole's pulses add at a stroke.
func (h *Simple) Extras(stroke int) ([]physics.Wall, []physics.Post) {
	var ws []physics.Wall
	var ps []physics.Post
	for _, p := range h.Pulses {
		if physics.There(stroke, p.Every, p.On, p.Phase) {
			ws = append(ws, p.Walls...)
			ps = append(ps, p.Posts...)
		}
	}
	return ws, ps
}

// PreviewWith plays a stroke of a round in some weather, read-only, the timed
// pieces starting at tick. A pulse piece that came back on the ball pushes it
// out, never across the hole's own walls. A ball left where the next stroke
// brings a hazard back returns to where this stroke started, as under a timed
// hazard (else that hazard would cost a stroke for nothing).
func (h *Simple) PreviewWith(ball physics.Vec2, angle, power float64, stroke, tick int, weather []physics.Zone) (physics.Shot, bool) {
	ws, ps := h.Extras(stroke)
	ball = physics.UnstickIn(ball, ws, ps, h.Course.Radius, h.Course.Walls)
	f := WithZones(WithExtras(h.Course, ws, ps), h.ExtraZones(stroke))
	f = physics.WithTick(WithWeather(f, weather), tick)
	shot, holed := Sink(f.Step(ball, Launch(angle, power), h.Substeps), h.Pin, h.CupRadius, h.Course.Radius)
	if !holed && len(shot.Path) > 0 {
		for _, z := range h.ExtraZones(stroke + 1) {
			if z.Kind == physics.Hazard && z.Contains(shot.Rest()) {
				shot.Path = append(shot.Path, ball)
				shot.Air = append(shot.Air, false)
				shot.Cause = append(shot.Cause, '-')
				break
			}
		}
	}
	return shot, holed
}

// Par is the strokes a good round takes: Strokes, 3 unless it says 1 to 19.
func (h *Simple) Par() int {
	if h.Strokes > 0 && h.Strokes < 20 {
		return h.Strokes
	}
	return 3
}

// Start is the tee.
func (h *Simple) Start() physics.Vec2 { return h.Tee }

// Cup is where the cup is.
func (h *Simple) Cup() physics.Vec2 { return h.Pin }

// Field is the course as the physics sees it.
func (h *Simple) Field() *physics.Field { return h.Course }

// Kick turns a stroke's power (0 to 10) into the ball's speed per substep,
// Kick·p^(3/4), so the roll (v²/2a) grows as p^(3/2). A full stroke rolls 44
// on the usual green, a board's length. Calibrated to keep every hole's par.
const Kick = 0.79

// Launch is the ball's starting velocity for a stroke. Every hole should use
// it, so that the same pull means the same shot on every course.
func Launch(angle, power float64) physics.Vec2 {
	if !(power > 0) {
		return physics.Vec2{}
	}
	return physics.FromPolar(angle, Kick*math.Sqrt(power*math.Sqrt(power)))
}

// minDrop is the least a ball falls to drop: a smaller ball drops as one of
// 0.5, else a point ball would drop into any cup at any speed.
const minDrop = 0.5

// Capture is the fastest a ball of radius ball crossing a cup of radius cup,
// off its centre by off, can go and still drop, in board units per substep;
// 0 when it cannot drop at all. Holmes's criterion (Am. J. Phys. 59, 1991):
// (2·sqrt(R² − b²) − r) · sqrt(G / 2r).
func Capture(cup, ball, off float64) float64 {
	c := cup*cup - off*off
	if !(c > 0) {
		return 0
	}
	if !(ball >= minDrop) {
		ball = minDrop
	}
	chord := 2*math.Sqrt(c) - ball
	if !(chord > 0) {
		return 0
	}
	return chord * math.Sqrt(physics.G/(2*ball))
}

// jumpStep is how much longer than the fastest drop a step must be for the
// one after it to be the rest of a jump, not a slow ball.
const jumpStep = 1.5

// Sink decides whether a shot ends in the cup: it stops within radius of the
// pin, or crosses the cup no faster than Capture allows a ball of radius
// ball. When it drops, the path is cut there and ends on the pin.
func Sink(shot physics.Shot, pin physics.Vec2, radius, ball float64) (physics.Shot, bool) {
	p := shot.Path
	top := Capture(radius, ball, 0) // over the middle: the fastest drop
	for i := 0; i+1 < len(p); i++ {
		a, d := p[i], p[i+1].Sub(p[i])
		if d.LenCmp(top) > 0 {
			continue // too fast, or a tunnel jump
		}
		if airborne(shot, i) || airborne(shot, i+1) {
			continue // flying over the cup is not dropping into it
		}
		// a short step right after a long one is not a slow ball: it is the
		// rest of a substep after a tunnel exit or a bounce
		if i > 0 && p[i].Sub(p[i-1]).LenCmp(top*jumpStep) > 0 {
			continue
		}
		// a step whose box is more than radius from the pin cannot drop
		if b, r := p[i+1], radius+1e-9; (pin.X < a.X-r && pin.X < b.X-r) || (pin.X > a.X+r && pin.X > b.X+r) ||
			(pin.Y < a.Y-r && pin.Y < b.Y-r) || (pin.Y > a.Y+r && pin.Y > b.Y+r) {
			continue
		}
		l := d.Len()
		t := 0.0
		if l > 0 {
			t = pin.Sub(a).Dot(d) / (l * l)
			if t < 0 {
				t = 0
			} else if t > 1 {
				t = 1
			}
		}
		at := a.Add(d.Scale(t))
		// the step's nearest point to the pin is where it crosses the cup
		if off := at.Sub(pin).Len(); off <= radius && l <= Capture(radius, ball, off) {
			cut := make([]physics.Vec2, 0, i+3)
			cut = append(cut, p[:i+1]...)
			shot.Path = append(cut, at, pin)
			if len(shot.Air) > i {
				shot.Air = append(append(make([]bool, 0, i+3), shot.Air[:i+1]...), false, false)
			}
			if len(shot.Cause) > i {
				shot.Cause = append(append(make([]byte, 0, i+3), shot.Cause[:i+1]...), '-', '-')
			}
			return shot, true
		}
	}
	if shot.Rest().Sub(pin).LenCmp(radius) <= 0 {
		shot.Path = append(shot.Path, pin)
		if shot.Air != nil {
			shot.Air = append(shot.Air, false)
		}
		if shot.Cause != nil {
			shot.Cause = append(shot.Cause, '-')
		}
		return shot, true
	}
	return shot, false
}

func airborne(s physics.Shot, i int) bool { return i < len(s.Air) && s.Air[i] }

package course

import (
	"errors"
	"math"

	"gno.land/p/nym-alexiscolin000/gnogolf/physics"
)

// Magic starts GG1, a hole as one little-endian binary string, frozen with
// this package: magic, header, field, skin table (str = u8 len + bytes),
// walls (style runs, then segments and, outside pulses, their Lengths),
// posts, zones, pulses; each list a count first. Encode is the layout.
const Magic = "GG1"

// The frozen limits Decode holds a hole to, pulses included.
const (
	MaxWalls     = 160
	MaxPosts     = 32
	MaxZones     = 32
	MaxPoly      = 64  // points in one polygon
	MaxPolyTotal = 512 // points in all of them
	MaxPulses    = 16
	MaxSkins     = 64
	MaxSubsteps  = 60
	MaxTiming    = 4096
	MaxOrder     = 999
	MaxWorld     = 16
)

const (
	flagRound = 1 << iota
	flagOutside
	flagAir
	flagCapped
)

// Encode is the hole as GG1. It stores what it is given: call it on a hole
// after Fit, with its walls prepared.
func Encode(h *Simple) string {
	e := &encoder{}
	f := h.Course
	if f == nil {
		f = &physics.Field{}
	}
	skins := map[string]int{}
	var table []string
	skin := func(s string) {
		if _, ok := skins[s]; !ok {
			skins[s] = len(table)
			table = append(table, s)
		}
	}
	pieces := func(ws []physics.Wall, ps []physics.Post, zs []physics.Zone) {
		for _, w := range ws {
			skin(w.Skin)
		}
		for _, p := range ps {
			skin(p.Skin)
		}
		for _, z := range zs {
			skin(z.Skin)
		}
	}
	pieces(f.Walls, f.Posts, f.Zones)
	for _, p := range h.Pulses {
		pieces(p.Walls, p.Posts, p.Zones)
	}

	e.b = append(e.b, Magic...)
	e.u16(h.W)
	e.u16(h.H)
	e.u8(h.Strokes)
	e.u16(h.Substeps)
	e.str(h.World)
	e.f64(h.Order)
	e.str(h.Title)
	e.vec(h.Tee)
	e.vec(h.Pin)
	e.f64(h.CupRadius)
	e.f64(h.Shelter)
	e.f64(f.Friction)
	e.f64(f.Bounce)
	e.f64(f.Radius)
	e.u16(len(table))
	for _, s := range table {
		e.str(s)
	}
	e.walls(f.Walls, skins, f.Radius, true)
	e.posts(f.Posts, skins)
	e.zones(f.Zones, skins)
	e.u8(len(h.Pulses))
	for _, p := range h.Pulses {
		e.i32(p.Every)
		e.i32(p.On)
		e.i32(p.Phase)
		e.walls(p.Walls, skins, f.Radius, false)
		e.posts(p.Posts, skins)
		e.zones(p.Zones, skins)
	}
	return string(e.b)
}

type encoder struct{ b []byte }

func (e *encoder) u8(n int)  { e.b = append(e.b, byte(n)) }
func (e *encoder) u16(n int) { e.b = append(e.b, byte(n), byte(n>>8)) }
func (e *encoder) i32(n int) {
	u := uint32(int32(n))
	e.b = append(e.b, byte(u), byte(u>>8), byte(u>>16), byte(u>>24))
}

func (e *encoder) f64(x float64) {
	u := math.Float64bits(x)
	e.b = append(e.b, byte(u), byte(u>>8), byte(u>>16), byte(u>>24), byte(u>>32), byte(u>>40), byte(u>>48), byte(u>>56))
}

func (e *encoder) vec(v physics.Vec2) {
	e.f64(v.X)
	e.f64(v.Y)
}

func (e *encoder) str(s string) {
	e.u8(len(s))
	e.b = append(e.b, s[:len(s)&0xff]...)
}

// sameStyle is whether two walls share everything but their segment.
func sameStyle(a, b *physics.Wall) bool {
	return math.Float64bits(a.Bounce) == math.Float64bits(b.Bounce) && a.Mark == b.Mark && a.Skin == b.Skin &&
		a.Every == b.Every && a.On == b.On && a.Phase == b.Phase
}

func (e *encoder) walls(ws []physics.Wall, skins map[string]int, r float64, lengths bool) {
	e.u16(len(ws))
	for i := 0; i < len(ws); {
		j := i + 1
		for j < len(ws) && sameStyle(&ws[i], &ws[j]) {
			j++
		}
		w := &ws[i]
		e.u16(j - i)
		e.f64(w.Bounce)
		e.i32(int(w.Mark))
		e.u16(skins[w.Skin])
		e.i32(w.Every)
		e.i32(w.On)
		e.i32(w.Phase)
		i = j
	}
	for _, w := range ws {
		e.vec(w.Seg.A)
		e.vec(w.Seg.B)
		if lengths {
			l, lp, lm := physics.Lengths(w.Seg, r)
			e.f64(l)
			e.f64(lp)
			e.f64(lm)
		}
	}
}

func (e *encoder) posts(ps []physics.Post, skins map[string]int) {
	e.u16(len(ps))
	for _, p := range ps {
		e.vec(p.C)
		e.f64(p.R)
		e.f64(p.Bounce)
		e.i32(int(p.Mark))
		e.u16(skins[p.Skin])
	}
}

func (e *encoder) zones(zs []physics.Zone, skins map[string]int) {
	e.u16(len(zs))
	for _, z := range zs {
		e.u8(int(z.Kind))
		flags := 0
		if z.Round {
			flags |= flagRound
		}
		if z.Outside {
			flags |= flagOutside
		}
		if z.Air {
			flags |= flagAir
		}
		if z.Capped {
			flags |= flagCapped
		}
		e.u8(flags)
		e.vec(z.Min)
		e.vec(z.Max)
		e.vec(z.Vec)
		e.f64(z.Scale)
		e.i32(int(z.Mark))
		e.u16(skins[z.Skin])
		e.i32(z.Every)
		e.i32(z.On)
		e.i32(z.Phase)
		e.u16(len(z.Poly))
		for _, p := range z.Poly {
			e.vec(p)
		}
	}
}

// Decode reads a GG1 hole; anything outside the format, its limits or its
// value bounds is an error, with nothing returned. It prepares the walls from
// the stored lengths (physics.PrepareWith) and trusts them: check them once
// with Exact, or use DecodeChecked, before accepting data from anyone.
func Decode(s string) (*Simple, error) {
	d := &decoder{s: s}
	if len(s) < len(Magic) || s[:len(Magic)] != Magic {
		return nil, errors.New("course: not GG1 data")
	}
	d.i = len(Magic)
	h := &Simple{}
	h.W, h.H = d.u16(), d.u16()
	h.Strokes = d.u8()
	h.Substeps = d.u16()
	h.World = d.str()
	h.Order = d.f64()
	h.Title = d.str()
	if d.err != "" {
		return nil, errors.New(d.err)
	}
	if h.W < 1 || h.W > MaxBoard || h.H < 1 || h.H > MaxBoard {
		return nil, errors.New("course: the board is 1 to 96 a side")
	}
	if h.Strokes > 19 {
		return nil, errors.New("course: par is at most 19")
	}
	if h.Substeps < 1 || h.Substeps > MaxSubsteps {
		return nil, errors.New("course: substeps are 1 to 60")
	}
	if !IsWorld(h.World) {
		return nil, errors.New("course: a world is 1 to 16 letters a-z")
	}
	if !(h.Order >= 0 && h.Order <= MaxOrder) {
		return nil, errors.New("course: order is 0 to 999")
	}
	d.w, d.h = float64(h.W), float64(h.H)
	h.Tee, h.Pin = d.point(), d.point()
	h.CupRadius, h.Shelter = d.f64(), d.f64()
	f := &physics.Field{}
	f.Friction, f.Bounce, f.Radius = d.f64(), d.f64(), d.f64()
	if d.err == "" {
		switch {
		case !(h.CupRadius > 0 && h.CupRadius <= 2):
			d.fail("the cup's radius is above 0 and at most 2")
		case !(h.Shelter >= 0 && h.Shelter <= 1):
			d.fail("shelter is 0 to 1")
		case !(f.Friction >= 0 && f.Friction < 1):
			d.fail("friction is 0 to below 1")
		case !bounce(f.Bounce):
			d.fail("a bounce is 0 to 1.5")
		case !(f.Radius >= 0 && f.Radius <= 1):
			d.fail("the ball's radius is 0 to 1")
		}
	}
	n := d.u16()
	if n > MaxSkins {
		d.fail("too many skins")
	}
	if d.err != "" {
		return nil, errors.New(d.err)
	}
	d.skins = make([]string, n)
	for i := range d.skins {
		d.skins[i] = d.str()
	}
	var lens []float64
	f.Walls, lens = d.walls(true)
	f.Posts = d.posts()
	f.Zones = d.zones()
	np := d.u8()
	if np > MaxPulses {
		d.fail("too many pulses")
	}
	if d.err != "" {
		return nil, errors.New(d.err)
	}
	if np > 0 {
		h.Pulses = make([]Pulse, np)
	}
	for i := range h.Pulses {
		p := &h.Pulses[i]
		p.Every, p.On, p.Phase = d.i32(), d.i32(), d.i32()
		if !timing(p.Every, p.On, p.Phase) {
			d.fail("a pulse's timing is out of bounds")
		}
		p.Walls, _ = d.walls(false)
		p.Posts = d.posts()
		p.Zones = d.zones()
		if d.err != "" {
			return nil, errors.New(d.err)
		}
	}
	if d.err != "" {
		return nil, errors.New(d.err)
	}
	if d.i != len(s) {
		return nil, errors.New("course: trailing bytes after the hole")
	}
	physics.PrepareWith(f, lens)
	h.Course = f
	return h, nil
}

// DecodeChecked is Decode, then Exact: for data anyone wrote. It costs a
// Prepare more; data once checked can be read back with Decode.
func DecodeChecked(s string) (*Simple, error) {
	h, err := Decode(s)
	if err != nil {
		return nil, err
	}
	if !Exact(h) {
		return nil, errors.New("course: the stored wall lengths are not the walls' own")
	}
	return h, nil
}

// Exact reports whether a decoded hole's stored lengths are its walls' own,
// its prep bit for bit the one Prepare works out. Use it on a value fresh from
// Decode: it prepares a copy of the field, which can panic on a hole stored in
// another realm (the copy keeps that realm's read-only mark).
func Exact(h *Simple) bool {
	if h.Course == nil {
		return false
	}
	got := physics.Prepared(h.Course)
	g := *h.Course
	physics.Prepare(&g)
	want := physics.Prepared(&g)
	if len(got) != len(want) {
		return false
	}
	for i := range want {
		if math.Float64bits(got[i]) != math.Float64bits(want[i]) {
			return false
		}
	}
	return true
}

// decoder reads GG1 with every read bounds-checked: past the end it records
// the error and reads zeros. Counts are checked against the limits before
// anything is allocated for them.
type decoder struct {
	s                               string
	i                               int
	err                             string
	w, h                            float64 // the board, for the coordinate bounds
	skins                           []string
	nWalls, nPosts, nZones, nPoints int // running totals, pulses included
}

func (d *decoder) fail(why string) {
	if d.err == "" {
		d.err = "course: " + why
	}
}

func (d *decoder) need(n int) bool {
	if d.i+n > len(d.s) {
		d.fail("truncated data")
		d.i = len(d.s)
		return false
	}
	return true
}

func (d *decoder) u8() int {
	if !d.need(1) {
		return 0
	}
	d.i++
	return int(d.s[d.i-1])
}

func (d *decoder) u16() int {
	if !d.need(2) {
		return 0
	}
	s, i := d.s, d.i
	d.i += 2
	return int(s[i]) | int(s[i+1])<<8
}

func (d *decoder) i32() int {
	if !d.need(4) {
		return 0
	}
	s, i := d.s, d.i
	d.i += 4
	return int(int32(uint32(s[i]) | uint32(s[i+1])<<8 | uint32(s[i+2])<<16 | uint32(s[i+3])<<24))
}

// f64 reads a float and refuses NaN and the infinities; -0 is kept.
func (d *decoder) f64() float64 {
	s, i := d.s, d.i
	if i+8 > len(s) {
		d.need(8)
		return 0
	}
	d.i = i + 8
	x := math.Float64frombits(uint64(s[i]) | uint64(s[i+1])<<8 | uint64(s[i+2])<<16 | uint64(s[i+3])<<24 |
		uint64(s[i+4])<<32 | uint64(s[i+5])<<40 | uint64(s[i+6])<<48 | uint64(s[i+7])<<56)
	if x-x != 0 { // NaN or an infinity
		d.fail("a number is not finite")
		return 0
	}
	return x
}

func (d *decoder) str() string {
	n := d.u8()
	if !d.need(n) {
		return ""
	}
	d.i += n
	return d.s[d.i-n : d.i]
}

// point reads a position, which must lie on the board or within 1 of it.
func (d *decoder) point() physics.Vec2 {
	x, y := d.f64(), d.f64()
	if !(x >= -1 && x <= d.w+1 && y >= -1 && y <= d.h+1) {
		d.fail("a point lies off the board")
	}
	return physics.Vec2{X: x, Y: y}
}

// corner reads a corner of a zone's box, which may lie up to MaxBoard off the
// board: Fit keeps a round or polygon zone's box whole.
func (d *decoder) corner() physics.Vec2 {
	x, y := d.f64(), d.f64()
	if !(x >= -MaxBoard && x <= d.w+MaxBoard && y >= -MaxBoard && y <= d.h+MaxBoard) {
		d.fail("a zone's box lies far off the board")
	}
	return physics.Vec2{X: x, Y: y}
}

func (d *decoder) skin() string {
	k := d.u16()
	if k >= len(d.skins) {
		d.fail("a skin index is out of range")
		return ""
	}
	return d.skins[k]
}

func bounce(b float64) bool { return b >= 0 && b <= 1.5 }

// timing is the bounds of Every/On/Phase: untimed is all zeros; timed, on at
// most every and phase below it.
func timing(every, on, phase int) bool {
	if every == 0 {
		return on == 0 && phase == 0
	}
	return every > 0 && every <= MaxTiming && on >= 0 && on <= every && phase >= 0 && phase < every
}

// IsWorld is whether w can name a world: 1 to MaxWorld letters a-z, as Decode
// holds data to.
func IsWorld(w string) bool {
	if len(w) < 1 || len(w) > MaxWorld {
		return false
	}
	for i := 0; i < len(w); i++ {
		if w[i] < 'a' || w[i] > 'z' {
			return false
		}
	}
	return true
}

// walls reads a wall list: its style runs, then its segments (and, with
// lengths, each wall's three Lengths).
func (d *decoder) walls(lengths bool) ([]physics.Wall, []float64) {
	n := d.u16()
	if d.nWalls += n; d.nWalls > MaxWalls {
		d.fail("too many walls")
	}
	if d.err != "" {
		return nil, nil
	}
	ws := make([]physics.Wall, n)
	for i := 0; i < n && d.err == ""; {
		count := d.u16()
		if count < 1 || count > n-i {
			d.fail("a wall style run does not fit the walls")
			break
		}
		w := physics.Wall{Bounce: d.f64(), Mark: rune(d.i32()), Skin: d.skin(), Every: d.i32(), On: d.i32(), Phase: d.i32()}
		if !bounce(w.Bounce) {
			d.fail("a bounce is 0 to 1.5")
		}
		if !timing(w.Every, w.On, w.Phase) {
			d.fail("a wall's timing is out of bounds")
		}
		for k := 0; k < count; k++ {
			ws[i+k] = w
		}
		i += count
	}
	// one bounds check, then le per float: most of a hole's floats are here
	size := 32
	if lengths {
		size = 56
	}
	if d.err != "" || !d.need(n*size) {
		return nil, nil
	}
	var lens []float64
	if lengths {
		lens = make([]float64, 3*n)
	}
	s, i := d.s, d.i
	for k := range ws {
		ax, ay, bx, by := le(s, i), le(s, i+8), le(s, i+16), le(s, i+24)
		if !(ax >= -1 && ax <= d.w+1 && ay >= -1 && ay <= d.h+1 && bx >= -1 && bx <= d.w+1 && by >= -1 && by <= d.h+1) {
			d.fail("a point lies off the board")
			return nil, nil
		}
		ws[k].Seg = physics.Segment{A: physics.Vec2{X: ax, Y: ay}, B: physics.Vec2{X: bx, Y: by}}
		if lengths {
			l, lp, lm := le(s, i+32), le(s, i+40), le(s, i+48)
			if l-l != 0 || lp-lp != 0 || lm-lm != 0 {
				d.fail("a number is not finite")
				return nil, nil
			}
			lens[3*k], lens[3*k+1], lens[3*k+2] = l, lp, lm
		}
		i += size
	}
	d.i = i
	return ws, lens
}

// le is the little-endian float at s[i:i+8]; the caller checked the length.
// f64 has it inline: a call more per float is gas on every decode.
func le(s string, i int) float64 {
	return math.Float64frombits(uint64(s[i]) | uint64(s[i+1])<<8 | uint64(s[i+2])<<16 | uint64(s[i+3])<<24 |
		uint64(s[i+4])<<32 | uint64(s[i+5])<<40 | uint64(s[i+6])<<48 | uint64(s[i+7])<<56)
}

func (d *decoder) posts() []physics.Post {
	n := d.u16()
	if d.nPosts += n; d.nPosts > MaxPosts {
		d.fail("too many posts")
	}
	if d.err != "" {
		return nil
	}
	ps := make([]physics.Post, n)
	for i := 0; i < n && d.err == ""; i++ {
		p := &ps[i]
		p.C = d.point()
		p.R, p.Bounce = d.f64(), d.f64()
		p.Mark, p.Skin = rune(d.i32()), d.skin()
		if !(p.R > 0 && p.R <= 8) {
			d.fail("a post's radius is above 0 and at most 8")
		}
		if !bounce(p.Bounce) {
			d.fail("a bounce is 0 to 1.5")
		}
	}
	return ps
}

func (d *decoder) zones() []physics.Zone {
	n := d.u16()
	if d.nZones += n; d.nZones > MaxZones {
		d.fail("too many zones")
	}
	if d.err != "" {
		return nil
	}
	zs := make([]physics.Zone, n)
	for i := 0; i < n && d.err == ""; i++ {
		z := &zs[i]
		kind, flags := d.u8(), d.u8()
		if kind > int(physics.Loop) {
			d.fail("a zone's kind is unknown")
		}
		if flags&^(flagRound|flagOutside|flagAir|flagCapped) != 0 {
			d.fail("a zone has unknown flags")
		}
		z.Kind = physics.ZoneKind(kind)
		z.Round, z.Outside, z.Air, z.Capped = flags&flagRound != 0, flags&flagOutside != 0, flags&flagAir != 0, flags&flagCapped != 0
		z.Min, z.Max = d.corner(), d.corner()
		switch z.Kind {
		case physics.Tunnel, physics.Hazard, physics.Loop:
			z.Vec = d.point() // a place on the board
		default:
			z.Vec = physics.Vec2{X: d.f64(), Y: d.f64()} // a push
			// no steeper than MaxSin (squared: no root; a NaN fails it)
			if max := physics.G * physics.MaxSin; !(z.Vec.X*z.Vec.X+z.Vec.Y*z.Vec.Y <= max*max) {
				d.fail("a slope pushes at most G·MaxSin (0.95)")
			}
		}
		z.Scale = d.f64()
		if !(z.Scale >= 0 && z.Scale <= 8) {
			d.fail("a zone's scale is 0 to 8")
		}
		z.Mark, z.Skin = rune(d.i32()), d.skin()
		z.Every, z.On, z.Phase = d.i32(), d.i32(), d.i32()
		if !timing(z.Every, z.On, z.Phase) {
			d.fail("a zone's timing is out of bounds")
		}
		np := d.u16()
		if np == 1 || np == 2 || np > MaxPoly {
			d.fail("a polygon has 3 to 64 points")
		}
		if d.nPoints += np; d.nPoints > MaxPolyTotal {
			d.fail("too many polygon points")
		}
		if d.err != "" {
			break
		}
		if np > 0 {
			z.Poly = make([]physics.Vec2, np)
			for k := range z.Poly {
				z.Poly[k] = d.point()
			}
		}
	}
	return zs
}

package golf

import (
	"chain"
	"chain/runtime"
	"crypto/sha256"
	"encoding/hex"
	"math"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"gno.land/p/nym-alexiscolin000/gnogolf/course"
)

// Holes as data: a version is a GG1 string, checked once at publish and kept
// as bytes; each call decodes it afresh and stores nothing of it. A version
// is never edited or removed: a new one takes its alias, and the old one is
// archived, still playable, its records kept.

// wearGrid is the entry's wear: a count of balls at rest per cell of the
// WearW by WearH grid, row-major.
func (e *entry) wearGrid() []int {
	out := make([]int, wearCells)
	if b := e.wear; b != nil {
		for i := range out {
			out[i] = int(uint32(b[4*i]) | uint32(b[4*i+1])<<8 | uint32(b[4*i+2])<<16 | uint32(b[4*i+3])<<24)
		}
	}
	return out
}

const wearCells = course.WearW * course.WearH

// mark counts a ball come to rest in wear cell i.
func (e *entry) mark(i int) {
	if i < 0 || i >= wearCells {
		return // course.WearIndexOn never gives one
	}
	if e.wear == nil {
		e.wear = make([]byte, 4*wearCells)
	}
	b := e.wear
	n := uint32(b[4*i]) | uint32(b[4*i+1])<<8 | uint32(b[4*i+2])<<16 | uint32(b[4*i+3])<<24
	n++
	b[4*i], b[4*i+1], b[4*i+2], b[4*i+3] = byte(n), byte(n>>8), byte(n>>16), byte(n>>24)
}

// maxData bounds a version's data: a hole at every limit of the format is
// about 21 KB.
const maxData = 32 << 10

// Publish puts a course hole's data into its slot as its next version and
// returns the new id ("garden/7/v2"). Only the owner can. hexData is the hole
// as course.Encode wrote it, in hex. slot must be the data's own world and
// order ("garden/7", order 1 to 999), so a mis-edited file cannot replace the
// wrong hole; the course holds at most 9999 slots (maxCourse). Data identical
// to the current version's is refused. The version it replaces is archived:
// its records stay, its bests leave the course standings. note (at most 140
// characters, cleaned) says why.
func Publish(cur realm, slot, hexData, note string) string {
	by := cur.Previous().Address()
	if !isOwner(by) {
		panic("golf: only the owner can publish a course hole")
	}
	h, data, sum := decodeData(hexData)
	if h.Order < 1 || h.Order != math.Trunc(h.Order) {
		panic("golf: a course hole's order is a whole number from 1 to 999")
	}
	own := h.World + "/" + strconv.Itoa(int(h.Order))
	if slot != own {
		panic("golf: this data is " + own + ", not " + slot)
	}
	key, ok := slotKeyOf(slot)
	if !ok {
		panic("golf: " + slot + " is not a course slot") // its data's own world/order: cannot happen
	}
	var old *entry
	n := 1
	if v := slots.Get(key); v != nil {
		old = find(v.(string))
		if old.sha == sum {
			panic(nothingNew(old))
		}
		n = old.version + 1
	} else if slots.Size() >= maxCourse {
		panic("golf: the course is full: 9999 slots")
	}
	e := dataEntry(slot, n, h, by, sum, note)
	e.official = true
	courseHoles.Set(e.id, e)
	holeData.Set(e.id, data)
	slots.Set(key, e.id)
	chain.Emit(EventHolePublished, "hole", e.id, "slot", slot, "sha", sum, "by", by.String(), "official", "true")
	if old != nil {
		retire(old, e.id)
	}
	return e.id
}

// PublishMine publishes a community hole of the caller's own and returns its
// id: "<caller>/<slug>/v1", then v2 and on. Anyone can while publishing is
// open (SetPublishing); only the same address adds versions. slug is 1 to 32
// of a-z, 0-9 and "-". The data is checked as Publish checks it, its world
// and order aside; its name and note carry no web address. It is playable and
// recorded, in no cup and not in the course ranking; a new version of a
// hidden hole stays hidden. The publisher pays the storage deposit (about
// half a GNOT a version), and nothing published can be deleted.
func PublishMine(cur realm, slug, hexData, note string) string {
	if !publishing {
		panic("golf: publishing community holes is not open yet")
	}
	by := cur.Previous().Address()
	if !validSlug(slug) {
		panic("golf: a slug is 1 to 32 of a-z, 0-9 and -")
	}
	alias := by.String() + "/" + slug
	h, data, sum := decodeData(hexData)
	var old *entry
	n := 1
	if v := aliases.Get(alias); v != nil {
		old = find(v.(string))
		if old.sha == sum {
			panic(nothingNew(old))
		}
		n = old.version + 1
	}
	e := dataEntry(alias, n, h, by, sum, note)
	if linkish(e.name) || linkish(e.note) {
		panic("golf: a community hole's name and note carry no web address")
	}
	community.Set(e.id, e)
	holeData.Set(e.id, data)
	aliases.Set(alias, e.id)
	if old != nil {
		old.next = e.id // archived; it never counted anywhere
	}
	if !hidden.Has(alias) { // a hidden hole has no row (Hide)
		a := by.String()
		// the newest row: the author's own moves to its height
		moveAuthor(a, newestRow(a), pad(int(e.height), 12))
		if old != nil {
			byAuthor.Remove(a + " " + recentKey(old.height, slug))
		}
		byAuthor.Set(a+" "+recentKey(e.height, slug), e.id)
	}
	chain.Emit(EventHolePublished, "hole", e.id, "slot", alias, "sha", sum, "by", by.String(), "official", "false")
	return e.id
}

// newestRow is the height of an author's newest row in byAuthor
// ("<address> <height> <slug>"), "" if they have none.
func newestRow(a string) string {
	latest := ""
	byAuthor.ReverseIterate(a+" ", a+"!", func(k string, _ any) bool {
		latest = k[len(a)+1 : len(a)+13]
		return true
	})
	return latest
}

// moveAuthor moves an author's own row in byAuthor (recentKey(height,
// address)) from the height was to now, "" for none: it stays at their
// newest row's, and goes with their last.
func moveAuthor(a, was, now string) {
	if was == now {
		return
	}
	if was != "" {
		byAuthor.Remove(was + " " + a)
	}
	if now != "" {
		byAuthor.Set(now+" "+a, nil)
	}
}

// linkish spots a web address in a community hole's name or note: "www.", a
// dot between a letter or digit and two letters ("claim.xyz", "t.me"; not
// "e.g."), or an IP address, look-alike dots (．。․﹒) read as dots, letters in
// any case. Basic (the owner can Hide what gets past) and strict on purpose
// ("St.Andrews" is refused). It reads s a byte at a time: every mark is
// ASCII, so a non-ASCII character is decoded only to tell İ and the Kelvin
// sign (which lower-case to ASCII), the look-alike dots and spaces apart.
func linkish(s string) bool {
	var c1, c2, c3 byte // the three characters before c, lower-cased
	// the word so far (as strings.Fields splits): an IP is digits, three dots
	word, ip, dots := false, true, 0
	for i := 0; i < len(s); {
		c, size, space := s[i], 1, false
		switch {
		case c >= 'A' && c <= 'Z':
			c += 'a' - 'A'
		case c >= utf8.RuneSelf:
			var r rune
			r, size = utf8.DecodeRuneInString(s[i:])
			switch r {
			case 'İ':
				c = 'i'
			case '\u212a': // the Kelvin sign
				c = 'k'
			case '．', '。', '․', '﹒':
				c = '.'
			default:
				c, space = utf8.RuneSelf, unicode.IsSpace(r) // none of the marks
			}
		case c == ' ' || c >= '\t' && c <= '\r':
			space = true
		}
		i += size
		switch {
		case c == '.' && c1 == 'w' && c2 == 'w' && c3 == 'w':
			return true
		case isLower(c) && isLower(c1) && c2 == '.' && (isLower(c3) || isDigit(c3)):
			return true
		}
		c1, c2, c3 = c, c1, c2
		if space {
			if word && ip && dots == 3 {
				return true
			}
			word, ip, dots = false, true, 0
			continue
		}
		word = true
		if c == '.' {
			dots++
		} else if !isDigit(c) {
			ip = false
		}
	}
	return word && ip && dots == 3
}

func isLower(c byte) bool { return c >= 'a' && c <= 'z' }
func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// decodeData checks a version's data as it arrives: hex, GG1 within the
// format's limits, stored lengths bit-exact (DecodeChecked: every later
// Decode trusts them), and in the one form Encode gives.
func decodeData(hexData string) (*course.Simple, string, string) {
	if len(hexData) > 2*maxData {
		panic("golf: the data is too long")
	}
	b, err := hex.DecodeString(hexData)
	if err != nil {
		panic("golf: the data is not hex")
	}
	data := string(b)
	h, err := course.DecodeChecked(data)
	if err != nil {
		panic("golf: " + err.Error())
	}
	// one hole, one string: data that decodes to a hole Encode would write
	// otherwise (a skin never used, a style run split, a stored length a
	// zero-length wall never reads) is refused, so the same hole cannot come
	// back under another sha
	if course.Encode(h) != data {
		panic("golf: the data is not as course.Encode writes it")
	}
	// refused if a transaction could not replay its heaviest shot, or if in
	// its dearest weather a commit's first shot would be capped below
	// minShotWork: every commit decodes the hole and draws its forecast first
	if newWork(h, nil).bound > maxShotGas {
		panic(errShotTooHeavy)
	}
	if worstGas(h, len(data)) > workBudget {
		panic(errTooStormy)
	}
	sum := sha256.Sum256(b)
	return h, data, hex.EncodeToString(sum[:])
}

// nothingNew refuses data identical to the alias's current version: it would
// reset the hole's ranking for nothing.
func nothingNew(old *entry) string {
	return "golf: this data is already " + old.id + ": nothing to publish"
}

func dataEntry(alias string, n int, h *course.Simple, by address, sum, note string) *entry {
	e := newEntry(alias+"/v"+strconv.Itoa(n), cleanName(h.Title), h.Par(), h.World, h.Order)
	e.slot, e.version, e.by, e.height, e.sha, e.note = alias, n, by, runtime.ChainHeight(), sum, cleanText(note, maxNote)
	return e
}

// worlds is the course's worlds in play order, with their names on the page.
var worlds = []struct{ id, name string }{
	{"garden", "Garden Cup"},
	{"island", "Island Cup"},
	{"town", "Mushroom Town"},
	{"mountain", "Mountain Cup"},
	{"mines", "Crystal Mines"},
}

// worldRank is a world's place among worlds; any other comes after.
func worldRank(w string) int {
	for i, x := range worlds {
		if x.id == w {
			return i
		}
	}
	return len(worlds)
}

// slotKey is a slot's key: its world's rank, the world, and the order in
// three digits, so the slots tree is in course order.
func slotKey(world string, order int) string {
	return string(rune('0'+worldRank(world))) + world + "/" + pad(order, 3)
}

// slotKeyOf reads a slot, "world/order" (as "garden/7"), into its key.
func slotKeyOf(slot string) (string, bool) {
	i := strings.Index(slot, "/")
	if i < 0 || !course.IsWorld(slot[:i]) {
		return "", false
	}
	n, err := strconv.Atoi(slot[i+1:])
	if err != nil || n < 1 || n > course.MaxOrder || strconv.Itoa(n) != slot[i+1:] {
		return "", false
	}
	return slotKey(slot[:i], n), true
}

func validSlug(s string) bool {
	if len(s) < 1 || len(s) > 32 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if c := s[i]; !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-') {
			return false
		}
	}
	return true
}

// HoleData is a version's GG1, in hex, as it was published (an alias gives
// its current version's): what a golf/v2 or an auditor reads back.
func HoleData(hole string) string {
	e := readHole(hole)
	return hex.EncodeToString([]byte(holeData.Get(e.id).(string)))
}

// Current is the id of the version an alias ("garden/7", "<address>/<slug>")
// plays now, "" if the alias has none.
func Current(alias string) string { return current(alias) }

// Versions is every version of an alias, oldest first (the newest pageMax if
// there are more): its id, number, the height it was published at, by whom,
// its data's sha256, its note, and the version that took its place. slot is
// the alias, "" (and no versions) for one that has none.
func Versions(alias string) string {
	now := find(current(alias))
	slot := ""
	if now != nil {
		slot = now.slot // never the caller's own bytes
	}
	var sb strings.Builder
	sb.WriteString("{" + versionJSON + `,"slot":` + jstr(slot) + `,"versions":[`)
	if now != nil {
		from := firstVersion(now)
		for n := from; n <= now.version; n++ {
			e := find(now.slot + "/v" + strconv.Itoa(n))
			sb.WriteString(sep(n-from) + `{"id":` + jstr(e.id) + `,"v":` + strconv.Itoa(e.version) +
				`,"height":` + strconv.FormatInt(e.height, 10) + `,"by":` + jstr(e.by.String()) +
				`,"sha":` + jstr(e.sha) + `,"note":` + jstr(e.note) + `,"next":` + jstr(e.next) + "}")
		}
	}
	sb.WriteString("]}")
	return sb.String()
}

// firstVersion is the oldest of now's versions a list shows: the newest
// pageMax are (now is its alias's current version).
func firstVersion(now *entry) int {
	if now.version > pageMax {
		return now.version - pageMax + 1
	}
	return 1
}

// BestOf is a player's best finished round on a hole in a mode, 0 if none.
func BestOf(hole, mode string, player address) int {
	e, m := readHole(hole), modeOf(mode)
	return bestStrokes(e.bests(m).Get(player.String()))
}

// Package golf is the game realm: it keeps the holes, the players' rounds,
// the records and the rankings. Every hole is data (a GG1 string, p/…/course),
// never code: golf decodes it and plays it with p/…/physics. The owner
// publishes the course's holes into slots of a cup ("garden/7"), each publish
// a new version ("garden/7/v2"); once the owner opens publishing, anyone can
// publish a community hole ("<address>/<slug>/v1", PublishMine), playable and
// recorded but outside the course and its ranking.
//
// Reads take a version's id or its alias ("garden/7", "<address>/<slug>"),
// its current version. Writes take the exact id only, as HoleState or Holes gave
// it: a round cannot be replayed on a version it was not played on.
//
// Who can change what (in full on the hub page): the owner holds one power,
// the course itself: its holes (Publish), what the lists show (Hide), and
// whether anyone can publish (SetPublishing).
package golf

import (
	"chain"
	"chain/runtime"
	"math"
	"strconv"
	"strings"
	"unicode"

	"gno.land/p/nym-alexiscolin000/gnogolf/course"
	"gno.land/p/nym-alexiscolin000/gnogolf/physics"
	"gno.land/p/nt/avl/v0"
	bptree "gno.land/p/nt/bptree/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/sys/users"
)

const (
	maxPower = 10.0
	// maxShots bounds a commit; its work (workBudget) may bound it lower.
	maxShots = 12
)

// The refusals said in more than one place.
const (
	errShot         = "golf: a shot is an angle and a power between 0 and 10"
	errStrokeLimit  = "golf: this round is over its stroke limit, Reset to play again"
	errShotTooHeavy = "golf: one shot on this hole could cost more than a transaction can replay"
	errTooStormy    = "golf: in its dearest weather, a commit on this hole would leave too little room for a shot"
	errUnknownHole  = "golf: unknown hole: "
)

type entry struct {
	id    string // "<alias>/v<n>"
	name  string // the hole's name, cleaned; frozen when it was published
	par   int    // frozen like the name
	world string // "garden", "island", "town": frozen too
	order float64
	// official: a version the owner published into a slot; only these rank
	official bool
	// its provenance, set at publish (the hole itself is never stored: hole())
	slot    string  // the alias it answers to: "garden/7", "<address>/<slug>"
	version int     // its number under that alias, from 1
	by      address // who published it
	height  int64
	sha     string // sha256 of its data, hex
	note    string
	wear    []byte // WearW*WearH little-endian u32 counters, made at its first play
	// Its rounds, bests and board are rows of the shared indexes (views), not
	// trees of its own, whose first leaf (a few KB) its first player would pay.
	plays int
	// the records per mode (rec), flat: a nested object costs a few hundred
	// bytes more
	best, proBest     int
	bestBy, proBestBy address
	next              string // the version that took this one's place, "" while it is current
	// its drain once archived (drain); nil if never archived
	out *draining
}

// record is the hole's record in one mode: who holds it, in how many
// strokes, 0 if never completed.
type record struct {
	by   address
	best int
}

// rec is the entry's record in mode m.
func (e *entry) rec(m int) record {
	if m == pro {
		return record{e.proBestBy, e.proBest}
	}
	return record{e.bestBy, e.best}
}

// roundTree is the version's rounds under way: player address -> *round. A
// round is stored from its first commit that does not finish it, and removed
// as it is holed (stroke) or Reset: a finish is kept as a best, not a round.
func (e *entry) roundTree() view { return view{rounds, e.id + " "} }

// bests is the version's results in mode m: player address -> their best
// finished round there, kept across replays, as bestOf writes it.
func (e *entry) bests(m int) view { return view{bests, e.id + " " + modeNames[m] + " "} }

// bestOf is how a best is kept: "<strokes> <height> <period> <shots>". The
// height ranks it before a later tie (boardKey); the period and shots let
// Ghost replay it in its own weather. The mode is in the key.
func bestOf(r *round) string {
	return strconv.Itoa(r.strokes) + " " + strconv.FormatInt(runtime.ChainHeight(), 10) + " " +
		strconv.FormatInt(r.period, 10) + " " + r.shots
}

// errBest is a best not as bestOf writes it: never written, refused if read.
const errBest = "golf: a best not as bestOf writes it: "

// bestStrokes is a kept best's strokes, 0 for none (a tree's nil).
func bestStrokes(v any) int {
	if v == nil {
		return 0
	}
	s := v.(string)
	i := strings.Index(s, " ")
	if i < 0 {
		panic(errBest + s)
	}
	n, err := strconv.Atoi(s[:i])
	if err != nil {
		panic(errBest + s)
	}
	return n
}

// bestFields is a kept best's height, period and shots.
func bestFields(v any) (int64, int64, string) {
	s := v.(string)
	f := strings.SplitN(s, " ", 4)
	if len(f) < 4 {
		panic(errBest + s)
	}
	at, err := strconv.ParseInt(f[1], 10, 64)
	period, err2 := strconv.ParseInt(f[2], 10, 64)
	if err != nil || err2 != nil {
		panic(errBest + s)
	}
	return at, period, f[3]
}

// board is the version's board in mode m: boardKey(best, player) ->
// player, the named players' bests, fewest strokes first.
func (e *entry) board(m int) view { return view{boards, e.id + " " + modeNames[m] + " "} }

// view is the rows of a shared index under prefix p, read and written
// without it. p ends with a space, which no id holds, so its rows are exactly
// the keys from p to p with the space made a "!".
type view struct {
	t *bptree.BPTree
	p string
}

func (v view) end() string                 { return v.p[:len(v.p)-1] + "!" }
func (v view) Get(k string) any            { return v.t.Get(v.p + k) }
func (v view) Has(k string) bool           { return v.t.Has(v.p + k) }
func (v view) Set(k string, x any) bool    { return v.t.Set(v.p+k, x) }
func (v view) Remove(k string) (any, bool) { return v.t.Remove(v.p + k) }
func (v view) Size() int                   { return before(v.t, v.end()) - before(v.t, v.p) }
func (v view) index(k string) int          { return before(v.t, v.p+k) - before(v.t, v.p) }
func (v view) strip(cb func(string, any) bool) func(string, any) bool {
	return func(k string, x any) bool { return cb(k[len(v.p):], x) }
}

// Iterate is the rows in [start, end) ascending, end "" for no bound.
func (v view) Iterate(start, end string, cb func(key string, x any) bool) bool {
	hi := v.end()
	if end != "" {
		hi = v.p + end
	}
	return v.t.Iterate(v.p+start, hi, v.strip(cb))
}

// IterateByOffset is count rows from the offset-th, fewer at the end.
func (v view) IterateByOffset(offset, count int, cb func(key string, x any) bool) bool {
	end := v.end()
	return v.t.IterateByOffset(before(v.t, v.p)+offset, count, func(k string, x any) bool {
		return k >= end || v.strip(cb)(k, x)
	})
}

// before is how many keys of t sort before k: a binary search by index.
func before(t *bptree.BPTree, k string) int {
	lo, hi := 0, t.Size()
	for lo < hi {
		mid := (lo + hi) / 2
		if key, _ := t.GetByIndex(mid); key < k {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}

// seeded is a shared index whose first leaf the deployer pays at init, not
// its first player. Its key "" sorts before every view's rows: no view sees it.
func seeded() *bptree.BPTree {
	t := bptree.NewBPTree32()
	t.Set("", nil)
	return t
}

func newEntry(id, name string, par int, world string, order float64) *entry {
	return &entry{id: id, name: name, par: par, world: world, order: order}
}

// hole is the entry's hole, decoded from its data for this call only: a
// public call decodes it once and passes it down, and it is never stored.
func (e *entry) hole() *course.Simple {
	s, err := course.Decode(holeData.Get(e.id).(string))
	if err != nil {
		panic("golf: the data of " + e.id + " does not decode: " + err.Error()) // checked at publish: cannot happen
	}
	return s
}

// draining is an archived hole's drain, per mode: the next player to take
// out, whether all are out, and the players whose first finish came after it
// was archived: never counted, so never taken out.
type draining struct {
	from  [modes]string
	done  [modes]bool
	fresh [modes]*avl.Tree // player -> true
}

type round struct {
	bx, by  float64 // the ball, exactly: flat, not a nested Vec2 object
	fx, fy  float64 // where the last stroke started: its path is replayed from there
	strokes int
	period  int64  // the weather it is played in: set by its first stroke
	shots   string // the decisions so far, "angle,power,tick;…": the round, replayable
	mode    int    // assisted or pro: set by its first stroke, like the weather
}

func (r *round) ball() physics.Vec2 { return physics.Vec2{X: r.bx, Y: r.by} }

// A round is played in one of two modes, each with its own records and
// rankings: assisted (the full aim preview) or pro (the preview cut short).
// The chain cannot see a screen: the mode is the player's word.
const (
	assisted = iota
	pro
	modes
)

// modeOf reads a mode's name: "assisted" (or "") or "pro"; anything else
// panics rather than answer for another mode.
func modeOf(name string) int {
	switch name {
	case "", "assisted":
		return assisted
	case "pro":
		return pro
	}
	panic(`golf: a mode is "assisted" or "pro", got: ` + name)
}

var modeNames = [modes]string{"assisted", "pro"}

// modeTitles is how the pages head a mode's board.
var modeTitles = [modes]string{"Assisted", "Pro"}

// The indexes are B+ trees (32 entries a leaf: far cheaper an entry than an
// AVL node). What players add goes to five of them, shared by every version
// and mode and seeded at init (views): a first player pays for their own rows
// only.
//
// A B+ tree must not change while it is iterated: no callback below writes
// to the tree it walks (drain walks a hole's bests and writes the standings).
var (
	// the course's versions, current and archived: id -> *entry
	courseHoles = bptree.NewBPTree32()
	// everyone else's published data: id -> *entry
	community = bptree.NewBPTree32()
	// id -> a version's GG1 string, apart from its entry so that listing
	// holes never loads it
	holeData = bptree.NewBPTree32()
	// slotKey(world, order) -> id of the current version there, in course order
	slots = bptree.NewBPTree32()
	// "<address>/<slug>" -> id of the current version of a community hole
	aliases = bptree.NewBPTree32()
	// the listed community holes, two kinds of row in one tree (one first
	// leaf to pay, not two):
	//   - "<address> " + recentKey(publish height, slug) -> id: an author's
	//     holes not hidden, newest last;
	//   - recentKey(their newest row's height, address) -> nil: one per
	//     author (moveAuthor), the latest to publish last.
	// A height is digits and an address "g1…": the two never mix.
	byAuthor = bptree.NewBPTree32()
	// "<address>/<slug>" -> true: community holes hidden (Hide), every
	// version, out of byAuthor; still playable
	hidden = avl.NewTree()
	// recentKey(archive height, id) -> id of an archived course version
	archived = bptree.NewBPTree32()
	// every version's rounds, bests and boards, under its id (views)
	rounds, bests, boards = seeded(), seeded(), seeded()
	// per mode: player -> *row, their standing over the official holes
	allTotals = seeded()
	totals    = [modes]view{{allTotals, "assisted "}, {allTotals, "pro "}}
	// per mode: rankKey(row) -> player, the named players with a hole, best
	// first
	allRanks = seeded()
	ranks    = [modes]view{{allRanks, "assisted "}, {allRanks, "pro "}}
	// per mode: rankKey(row) -> player, standings with no hole left (setRow)
	idle = [modes]view{{allRanks, "idle assisted "}, {allRanks, "idle pro "}}
	// archived holes still in the standings, oldest first (drain)
	archiving []string
)

// row is one player's standing across the course: their best on each hole
// counted, summed, and those holes' pars, summed. Its score against par,
// strokes - par, is what ranks it after its holes.
type row struct {
	player              string
	holes, strokes, par int
	height              int64 // of the finish that last improved it: the first there ranks first
}

const topSize = 10

// named reports whether a player has a gno.land name (r/sys/users). Only
// named players rank: a name takes a registration, so a script cannot fill
// the boards with free addresses. Every finish is still kept.
func named(player string) bool {
	return !users.ResolveAddress(address(player)).IsDeleted()
}

// nameOf is a named player's name, "" for anyone else.
func nameOf(player string) string {
	if u := users.ResolveAddress(address(player)); !u.IsDeleted() && nameish(u.Name()) {
		return u.Name()
	}
	return ""
}

// nameish is a name as r/sys/users registers it (a-z, then a-z, 0-9, "_" and
// "-", at most 64), checked again because the pages print names in links.
func nameish(n string) bool {
	if n == "" || len(n) > 64 || n[0] < 'a' || n[0] > 'z' {
		return false
	}
	for i := 0; i < len(n); i++ {
		if c := n[i]; !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_' || c == '-') {
			return false
		}
	}
	return true
}

// find is the hole with this exact id, nil if none.
func find(id string) *entry {
	if v := courseHoles.Get(id); v != nil {
		return v.(*entry)
	}
	if v := community.Get(id); v != nil {
		return v.(*entry)
	}
	return nil
}

// current is the id an alias points at now: a course slot's or a community
// hole's current version; "" if it is neither.
func current(alias string) string {
	if k, ok := slotKeyOf(alias); ok {
		if v := slots.Get(k); v != nil {
			return v.(string)
		}
		return ""
	}
	if v := aliases.Get(alias); v != nil {
		return v.(string)
	}
	return ""
}

// mustHole is the hole a write names: its exact id. An alias is refused: a
// new version may have taken its place since the round's shots were chosen.
func mustHole(id string) *entry {
	if e := find(id); e != nil {
		return e
	}
	if now := current(id); now != "" {
		panic("golf: " + id + " is an alias: play its version by id, " + now)
	}
	panic(errUnknownHole + id)
}

// readHole is the hole a read names: an exact id, or an alias for its
// current version.
func readHole(id string) *entry {
	if e := find(id); e != nil {
		return e
	}
	if now := current(id); now != "" {
		return find(now)
	}
	panic(errUnknownHole + id)
}

// recentKey orders by height, then by what is at that height.
func recentKey(height int64, what string) string { return pad(int(height), 12) + " " + what }

// pad writes n in width digits, zeros first: keys that sort as numbers.
func pad(n, width int) string {
	s := strconv.Itoa(n)
	for len(s) < width {
		s = "0" + s
	}
	return s
}

// rankKey orders the course ranking: most holes first, then the best score
// against par (a hole at par counts the same whatever its par), then the
// first there, then the address. The score is signed: vsParBias puts it in
// seven digits. The holes take five: a standing can count more than the
// course's slots while a republished hole drains (its old best still counts,
// its new one adds a hole), so they get room well past maxCourse.
func rankKey(r *row) string {
	return pad(99999-r.holes, 5) + "/" + pad(vsParBias+r.strokes-r.par, 7) + "/" + pad(int(r.height), 12) + "/" + r.player
}

// maxCourse bounds the course's slots (Publish); a standing's holes are at
// most those plus the archived versions drain has not taken it out of yet.
// vsParBias is more than a standing can be under or over par: a hole is -18
// to +59 (1 to 60 strokes, par 1 to 19), so a full course at most 9999 * 59 =
// 589,941 over, 179,982 under, and the seven digits hold 55,555 holes.
const (
	maxCourse = 9999
	vsParBias = 1000000
)

// boardKey orders a hole's board by each player's best v: fewest strokes,
// then the first to make them (a best's shots are public: whoever replays
// them ties it and ranks after), then the address.
func boardKey(v any, player string) string {
	at, _, _ := bestFields(v)
	return pad(bestStrokes(v), 3) + "/" + pad(int(at), 12) + "/" + player
}

// boardStrokes is the strokes of a board's key: always its three digits.
func boardStrokes(k string) int {
	n, err := strconv.Atoi(k[:3])
	if err != nil {
		panic("golf: bad board key: " + k) // pad writes three digits: cannot happen
	}
	return n
}

// setRow moves a player's standing, as of height at, and keeps the ranking
// in step. A standing with no hole left is not freed, nor its key, which
// moves to idle: its deposit is the player's, and freeing it would refund
// whoever drained it. It moves back at the player's next hole.
func setRow(m int, r *row, holes, strokes, par int, at int64) {
	k := rankKey(r)
	_, had := ranks[m].Remove(k)
	if _, ok := idle[m].Remove(k); ok {
		had = true
	}
	r.holes, r.strokes, r.par, r.height = holes, strokes, par, at
	switch {
	case r.holes > 0 && named(r.player):
		ranks[m].Set(rankKey(r), r.player)
	case had:
		idle[m].Set(rankKey(r), r.player)
	}
}

// improve moves a player's standing by a new best on an official hole of par
// par (was: their old best there, 0 if none): only those count, or anyone's
// own hole would be a way to the top. The standing is kept, not recomputed,
// so a finish costs the same however many play.
func improve(m int, player string, par, was, best int) {
	r := &row{player: player}
	if v := totals[m].Get(player); v != nil {
		r = v.(*row)
	} else {
		totals[m].Set(player, r)
	}
	if was == 0 {
		setRow(m, r, r.holes+1, r.strokes+best, r.par+par, runtime.ChainHeight())
	} else {
		setRow(m, r, r.holes, r.strokes+best-was, r.par, runtime.ChainHeight())
	}
}

// retire archives an official hole replaced by next. Its bests stay there as
// its records but leave the course standings, in batches (drain): the Publish
// takes retireBatch, each course finish finishBatch, a Drain up to drainMax.
func retire(old *entry, next string) {
	old.next, old.out = next, &draining{}
	archived.Set(recentKey(runtime.ChainHeight(), old.id), old.id)
	archiving = append(archiving, old.id)
	chain.Emit(EventHoleRetired, "hole", old.id, "next", next)
	drain(retireBatch)
}

// How many archived players a Publish, a course finish and a Drain take out
// of the standings: sized so none costs more however many played.
const (
	retireBatch = 150
	finishBatch = 4
	drainMax    = 400
)

// drain takes up to n archived players out of the standings, oldest
// archived hole first.
func drain(n int) {
	for n > 0 && len(archiving) > 0 {
		e := find(archiving[0])
		d := e.out
		for m := 0; m < modes && n > 0; m++ {
			if d.done[m] {
				continue
			}
			stopped := e.bests(m).Iterate(d.from[m], "", func(p string, v any) bool {
				if n == 0 {
					d.from[m] = p
					return true
				}
				if d.fresh[m] == nil || !d.fresh[m].Has(p) {
					if t := totals[m].Get(p); t != nil {
						r := t.(*row)
						setRow(m, r, r.holes-1, r.strokes-bestStrokes(v), r.par-e.par, r.height)
					}
				}
				n--
				return false
			})
			if !stopped {
				d.done[m] = true
			}
		}
		if d.done[assisted] && d.done[pro] {
			if len(archiving) == 1 {
				archiving = nil // the backing array goes with it
			} else {
				archiving = archiving[1:]
			}
		}
	}
}

// Drain takes up to n players (1 to 400) of archived holes out of the course
// standings, sooner than the finishes would, and returns how many archived
// holes still have players in them. Anyone can call it. A standing it
// empties is kept at 0 holes (setRow): nothing is refunded to the caller.
func Drain(cur realm, n int) int {
	if n < 1 {
		n = 1
	}
	if n > drainMax {
		n = drainMax
	}
	drain(n)
	return len(archiving)
}

// counts reports whether a best on e by player (was: their previous best, 0
// if none) moves their standing: e is a current official hole, or an archived
// one whose drain has not reached them yet and where they already counted. A
// first finish on an archived hole never counts.
func counts(e *entry, m int, player string, was int) bool {
	if !e.official {
		return false
	}
	if e.next == "" {
		return true
	}
	if was == 0 || e.out.done[m] || player < e.out.from[m] {
		return false
	}
	return e.out.fresh[m] == nil || !e.out.fresh[m].Has(player)
}

// Launch plays one shot of the caller's round on hole (an exact id): angle in
// degrees (0 = right, 90 = down), power in (0, 10]. It is how gnoweb plays,
// with no aim preview, so its rounds are pro rounds. It answers with where
// the ball stopped, or the score if holed; PlayRoundAt commits many shots.
func Launch(cur realm, hole string, angle, power float64) string {
	e := mustHole(hole)
	h := e.hole()
	player := cur.Previous().Address()
	r := roundOf(e, h, player)
	fresh := r.strokes == 0
	if fresh {
		r.period = Period() // a round starts in the weather of the moment, and keeps it
		r.mode = pro
	} else if r.mode != pro {
		panic(otherMode(r))
	}

	fc := weatherOf(e, h, r.period)
	w := newWork(h, fc.Zones)
	w.fixed = fixedGas(e, fc)
	w.next(h)
	shot, holed := stroke(e, h, r, player, angle, power, 0, fc.Zones)
	w.add(shot)
	if holed {
		return ufmt.Sprintf("Holed in %d on %s! Your best there: %s:%s/%s", r.strokes, e.id, hub, e.id, player.String())
	}
	if fresh {
		e.roundTree().Set(player.String(), r)
	}
	// what a gnoweb player needs for the next shot
	a, d := aim(r.ball(), h.Cup())
	return ufmt.Sprintf("Stroke %d on %s: the ball stopped %.1f from the cup, which is at %.0f° from it. Your round: %s:%s/%s",
		r.strokes, e.id, d, a, hub, e.id, player.String())
}

// aim is the angle, in the shot's degrees, and the straight-line distance
// from a ball to the cup: walls and slopes are the player's to allow for.
func aim(from, cup physics.Vec2) (float64, float64) {
	d := cup.Sub(from)
	a := math.Atan2(d.Y, d.X) * 180 / math.Pi
	if a < 0 {
		a += 360
	}
	return a, d.Len()
}

// PlayRound is PlayRoundAt in the current period, for a caller with none to
// give (a form, a script); a round under way keeps its own. Prefer
// PlayRoundAt: a commit included after the weather turned is then played in
// the weather its shots were chosen in.
func PlayRound(cur realm, hole string, shots string) string {
	e, p := mustHole(hole), cur.Previous().Address()
	period := Period()
	if v := e.roundTree().Get(p.String()); v != nil { // (a round is kept from its first stroke on)
		period = v.(*round).period // stroke() still refuses a stale one
	}
	return playRound(e, p, shots, period, assisted)
}

// PlayRoundAt replays shots into the caller's assisted round on hole (an
// exact id), continuing it, in the weather of period: the current one or the
// one before, and a round under way keeps its own. The client sends
// decisions, never outcomes: the chain replays them.
//
// shots is "angle,power[,tick];…" (MsgCall carries no slice), at most 12,
// fewer on a heavy hole: a commit past the work budget is refused with the
// number of shots that fit, and the rest goes in the next commit.
func PlayRoundAt(cur realm, hole string, shots string, period int64) string {
	return playRound(mustHole(hole), cur.Previous().Address(), shots, period, assisted)
}

// PlayRoundPro is PlayRoundAt for a round played in pro mode: the aim
// preview cut short. It counts on the pro records and rankings only.
func PlayRoundPro(cur realm, hole string, shots string, period int64) string {
	return playRound(mustHole(hole), cur.Previous().Address(), shots, period, pro)
}

func playRound(e *entry, player address, shots string, period int64, mode int) string {
	h := e.hole()
	r := roundOf(e, h, player)
	fresh := r.strokes == 0
	if fresh {
		playablePeriod(period)
		r.period, r.mode = period, mode
	} else if r.period != period {
		panic(ufmt.Sprintf("golf: this round is being played in the weather of period %d", r.period))
	} else if r.mode != mode {
		panic(otherMode(r))
	}

	list := shotList(shots)
	fc := weatherOf(e, h, r.period) // once for the whole commit
	weather := fc.Zones
	w := newWork(h, weather)
	w.fixed = fixedGas(e, fc)
	for _, s := range list {
		w.next(h)
		angle, power, tick := parseShot(s)
		shot, holed := stroke(e, h, r, player, angle, power, tick, weather)
		w.add(shot)
		if holed {
			return ufmt.Sprintf("holed in %d strokes", r.strokes)
		}
	}
	if fresh { // under way: stored from its first commit
		e.roundTree().Set(player.String(), r)
	}
	return ufmt.Sprintf("%d shots replayed, ball at %.1f,%.1f after %d strokes",
		w.played, r.bx, r.by, r.strokes)
}

// otherMode refuses to go on with a round in a mode it was not started in.
func otherMode(r *round) string {
	return "golf: this round is being played in " + modeNames[r.mode] + " mode"
}

// shotList is a commit's shots: the non-empty entries of "a,p;a,p;…", at
// least one and at most maxShots.
func shotList(shots string) []string {
	var list []string
	for _, s := range strings.Split(shots, ";") {
		if s = strings.TrimSpace(s); s == "" {
			continue
		}
		if len(list) == maxShots {
			panic("golf: too many shots in one commit")
		}
		list = append(list, s)
	}
	if len(list) == 0 {
		panic("golf: no shots")
	}
	return list
}

// work is a commit's estimated gas so far. A shot counts the larger of its
// path's estimate and its Shot.Work's, plus its pulses' set-up, on top of
// what the commit spent before its shots (fixed: decoding, forecast). A shot
// that could pass workBudget is refused before anything is kept, and each is
// played under a work cap (physics.Field.Cap), so no commit can pass it; the
// client mirrors the model. An estimate, not a gas meter: see docs/golf.md,
// "The work budget".
type work struct {
	walls, pieces int64 // on the board this commit: walls, and every piece and polygon edge
	setup         int64 // what each shot spends outside its Shot.Work: a pulse's pieces, set up afresh
	bound         int64 // shotBound, and the set-up
	fixed         int64 // spent before the shots: decoding, forecast
	spent, most   int64
	played        int
	cap           int // the work cap of the shot being played
}

// The budget: of the 2e9 gas a wallet lets a transaction simulate, 1.4e9 for
// a commit, decoding and forecast included; the rest for package loads and
// bookkeeping.
const (
	workBudget   = 1400000000
	workPerShot  = 10000000
	workPerWall  = 150000
	workPerPoint = 1200000
	workPerPiece = 15000
	workPerUnit  = 1000
	// a pulse's walls and posts, set up afresh for each shot outside its
	// Shot.Work
	workPerPulseWall = 700000
	workPerPulsePost = 200000
)

// Decoding a hole's data costs at most decodeBase and decodePerByte a byte.
const (
	decodeBase    = 6000000
	decodePerByte = 4000
)

// fixedGas is what a commit on e spends before its shots, in the forecast
// fc: decoding the hole, and drawing the forecast.
func fixedGas(e *entry, fc course.Forecast) int64 {
	return decodeGas(len(holeData.Get(e.id).(string))) + int64(fc.Work)*workPerUnit
}

// decodeGas bounds decoding size bytes of a hole's data.
func decodeGas(size int) int64 { return decodeBase + decodePerByte*int64(size) }

// maxShotGas bounds a hole's heaviest shot (shotBound and its pulses'
// set-up): a hole past it is refused at publish.
const maxShotGas = 1300000000

// minShotWork is the work, in the physics' units, a commit's first shot may
// always do whatever the weather: four fifths of MaxWork. A shot is capped at
// what is left of the budget (work.next), so a hole whose dearest weather
// would leave less is refused at publish (worstGas): on a published hole,
// every shot of less than minShotWork plays out in any weather (as a commit's
// first, if need be), and an author whose board is too heavy is told at
// publish, not by a hole that misbehaves in the rain. A shot past it may be
// cut short; none is known: the course's heaviest real shot does 441,737
// over the full grid of tee shots (mountain/16, full power, in a storm), and
// the heaviest found in an adversarial search 0.74 of MaxWork (docs/golf.md);
// the course's tightest room in its dearest weather is 839,278 (mountain/7),
// 39,278 over the floor.
const minShotWork = 4 * physics.MaxWork / 5

// worstGas is what a commit on h (size bytes of data) spends up to a first
// shot of minShotWork in its dearest weather: decoding, the forecast at its
// most (course.WorstForecastWork), and the shot, its walls and its pulses'
// set-up, as work.next caps it.
func worstGas(h *course.Simple, size int) int64 {
	w := newWork(h, nil)
	return decodeGas(size) + int64(course.WorstForecastWork(h))*workPerUnit +
		workPerShot + w.walls*workPerWall + w.setup + (physics.MaxWorkStep+minShotWork)*workPerUnit
}

// newWork is a commit's work on a hole, before any shot: its walls and
// pieces, a pulse's as if always there, and the weather's.
func newWork(h *course.Simple, weather []physics.Zone) *work {
	w := &work{}
	if f := h.Field(); f != nil {
		w.walls = int64(len(f.Walls))
		w.pieces = pieces(f.Walls, f.Posts, f.Zones)
	}
	for _, p := range h.Pulses {
		w.walls += int64(len(p.Walls))
		w.pieces += pieces(p.Walls, p.Posts, p.Zones)
		w.setup += int64(len(p.Walls))*workPerPulseWall + int64(len(p.Posts))*workPerPulsePost
	}
	w.pieces += pieces(nil, nil, weather)
	w.bound = shotBound(w.walls) + w.setup
	return w
}

// shotBound is the most one shot on a board of walls walls can cost: the
// physics ends a stroke at MaxWork, passing it by MaxWorkStep at most.
func shotBound(walls int64) int64 {
	return workPerShot + walls*workPerWall + (physics.MaxWork+physics.MaxWorkStep)*workPerUnit
}

// pieces counts what a ball is tested against: each wall, post and zone, and
// each edge of a zone's polygon.
func pieces(ws []physics.Wall, ps []physics.Post, zs []physics.Zone) int64 {
	n := len(ws) + len(ps) + len(zs)
	for i := range zs {
		n += len(zs[i].Poly)
	}
	return int64(n)
}

// next refuses the next shot if it could overrun the budget, and caps its
// work at what is left of it.
func (w *work) next(h *course.Simple) {
	if w.played == 0 && w.bound > workBudget {
		w.refuse()
	}
	if w.played > 0 && w.spent+w.most > workBudget {
		w.refuse()
	}
	c := (workBudget-w.fixed-w.spent-workPerShot-w.walls*workPerWall)/workPerUnit - physics.MaxWorkStep
	c -= w.setup / workPerUnit
	if c < 1 {
		w.refuse()
	}
	if c > physics.MaxWork {
		c = physics.MaxWork
	}
	w.cap = int(c)
	if f := h.Field(); f != nil {
		f.Cap = w.cap // the decoded hole of this call only: never stored
	}
}

// refuse refuses the shot being played: it does not fit the budget.
func (w *work) refuse() {
	if w.played == 0 {
		panic(errShotTooHeavy)
	}
	panic(ufmt.Sprintf("golf: more shots than one transaction can replay on this hole: commit the first %d, then the rest", w.played))
}

func (w *work) add(s physics.Shot) {
	if w.cap < physics.MaxWork && s.Work > w.cap {
		w.refuse() // it reached its cap: it would have gone further
	}
	c := workPerShot + w.walls*workPerWall + int64(len(s.Path))*(workPerPoint+w.pieces*workPerPiece)
	if u := workPerShot + w.walls*workPerWall + int64(s.Work)*workPerUnit; u > c {
		c = u // a shot that did more than its path shows
	}
	c += w.setup
	w.spent += c
	if c > w.most {
		w.most = c
	}
	w.played++
}

// Reset abandons the caller's round under way on hole (an exact id), freeing
// its storage: the next stroke starts a new one from the tee. A finished round
// is not kept (its best is), so a new one needs no Reset. With no round under
// way it does nothing, and says nothing.
func Reset(cur realm, hole string) {
	e := mustHole(hole)
	player := cur.Previous().Address().String()
	if _, ok := e.roundTree().Remove(player); ok {
		chain.Emit(EventRoundReset, "hole", e.id, "player", player)
	}
}

// validShot refuses what would poison a round and returns the shot as
// recorded. NaN and infinities pass every comparison, so they are refused by
// name. The power is quantized before it is checked (0.00001 would round to
// 0). The angle is brought into (-360, 360), so a huge one cannot overflow to
// NaN in the physics, and again after rounding (-359.99996 is -0, not -360).
func validShot(angle, power float64) (float64, float64) {
	power = q4(power)
	if math.IsNaN(angle) || math.IsInf(angle, 0) || !(power > 0 && power <= maxPower) {
		panic(errShot)
	}
	angle = q4(math.Mod(angle, 360))
	if angle <= -360 || angle >= 360 {
		angle = math.Mod(angle, 360)
	}
	return angle, power
}

// resolve checks what the physics returned for a stroke: a path a read may
// print, and a ball that is a number. A hole is anyone's data.
func resolve(shot physics.Shot, holed bool) (physics.Shot, bool) {
	if len(shot.Path) > maxPath {
		panic("golf: the hole returned an oversized path")
	}
	rest := shot.Rest()
	if math.IsNaN(rest.X) || math.IsNaN(rest.Y) || math.IsInf(rest.X, 0) || math.IsInf(rest.Y, 0) {
		panic("golf: the hole returned a ball off the board")
	}
	return shot, holed
}

// back brings a ball that came to rest off the board (a leak in a hole's
// walls) back to from, where the shot started; the stroke counts, with no
// penalty. Every stroke golf plays or replays goes through it.
func back(h *course.Simple, from physics.Vec2, shot physics.Shot, holed bool) physics.Shot {
	rest := shot.Rest()
	w, hh := h.W, h.H
	if holed || len(shot.Path) == 0 || (rest.X >= 0 && rest.X <= float64(w) && rest.Y >= 0 && rest.Y <= float64(hh)) {
		return shot
	}
	// copies: the hole's own slices are the hole's
	shot.Path = append(append(make([]physics.Vec2, 0, len(shot.Path)+1), shot.Path...), from)
	shot.Air = append(append(make([]bool, 0, len(shot.Air)+1), shot.Air...), false)
	shot.Cause = append(append(make([]byte, 0, len(shot.Cause)+1), shot.Cause...), '-')
	return shot
}

// stroke resolves one shot into the round and reports whether it was holed.
func stroke(e *entry, h *course.Simple, r *round, player address, angle, power float64, tick int, weather []physics.Zone) (physics.Shot, bool) {
	if r.strokes >= maxRoundStrokes {
		panic(errStrokeLimit)
	}
	notOver(r.period) // every stroke, not only the first
	// played exactly as it is recorded, so the record replays
	angle, power = validShot(angle, power)

	from := r.ball()
	shot, holed := resolve(h.PreviewWith(from, angle*math.Pi/180, power, r.strokes, tick, weather))
	shot = back(h, from, shot, holed)
	w, hh := h.W, h.H
	e.mark(course.WearIndexOn(shot.Rest(), w, hh)) // where the round's ball is: back's, for a leak
	// the decisions, as played: what anyone needs to replay the round
	if r.shots != "" {
		r.shots += ";"
	}
	played := ufmt.Sprintf("%.4f,%.4f,%d", angle, power, tick)
	r.shots += played
	rest := shot.Rest()
	r.fx, r.fy, r.bx, r.by = from.X, from.Y, rest.X, rest.Y
	r.strokes++
	e.plays++

	if !holed {
		chain.Emit(EventShot, "hole", e.id, "player", player.String(),
			"strokes", strconv.Itoa(r.strokes), "mode", modeNames[r.mode], "shot", played)
		return shot, false
	}
	m, p := r.mode, player.String()
	// a player's best stays theirs: replaying the hole never erases it, and a
	// tie keeps the older round, shots and all
	best := e.bests(m).Get(p)
	if was := bestStrokes(best); was == 0 || r.strokes < was {
		if was > 0 {
			e.board(m).Remove(boardKey(best, p))
		}
		best = bestOf(r)
		e.bests(m).Set(p, best)
		if counts(e, m, p, was) {
			improve(m, p, e.par, was, r.strokes)
		} else if was == 0 && e.official && e.next != "" && !e.out.done[m] && p >= e.out.from[m] {
			// the drain has yet to reach this first finish: it was never
			// counted, so it must not be taken out
			if e.out.fresh[m] == nil {
				e.out.fresh[m] = avl.NewTree()
			}
			e.out.fresh[m].Set(p, true)
		}
	}
	if named(p) {
		seat(e, m, p, best)
	}
	if e.official {
		drain(finishBatch) // only the course's finishes pay for the course's drain
	}
	chain.Emit(EventHoled, "hole", e.id, "player", p,
		"strokes", strconv.Itoa(r.strokes), "mode", modeNames[m], "shots", r.shots)
	// the round is its best now, or no better than it: not kept (a round of
	// this commit's alone was never stored)
	e.roundTree().Remove(p)
	return shot, true
}

// seat puts a named player where their best puts them: on the hole's board,
// in its record if it tops it, and in the course ranking if they stand in it.
// Every finish does it, improved or not, so a player named since ranks.
func seat(e *entry, m int, p string, best any) {
	k := boardKey(best, p)
	if !e.board(m).Has(k) {
		e.board(m).Set(k, p)
	}
	// the record is a named player's (a throwaway address could hold it for
	// good) and the board's top, so a tie goes to the first to make it
	if n, rec := bestStrokes(best), e.rec(m); rec.best == 0 || n < rec.best ||
		n == rec.best && address(p) != rec.by && k < boardKey(e.bests(m).Get(rec.by.String()), rec.by.String()) {
		if m == pro {
			e.proBest, e.proBestBy = n, address(p)
		} else {
			e.best, e.bestBy = n, address(p)
		}
	}
	if v := totals[m].Get(p); v != nil && v.(*row).holes > 0 {
		if rk := rankKey(v.(*row)); !ranks[m].Has(rk) {
			idle[m].Remove(rk) // a standing parked while unnamed leaves idle as it ranks
			ranks[m].Set(rk, p)
		}
	}
}

// Claim ranks the caller's bests kept while they had no name: on the boards
// of the course's current holes, in both modes, and in the course ranking.
// It returns how many bests it seated, and refuses a caller with no gno.land
// name. It reads the course's holes only, so it costs the same for everyone.
func Claim(cur realm) int {
	p := cur.Previous().Address().String()
	if !named(p) {
		panic("golf: take a gno.land name first: only named players are ranked")
	}
	n := 0
	slots.Iterate("", "", func(_ string, v any) bool {
		e := find(v.(string))
		for m := 0; m < modes; m++ {
			if best := e.bests(m).Get(p); best != nil {
				seat(e, m, p, best)
				n++
			}
		}
		return false
	})
	return n
}

// maxRoundStrokes bounds a round's history (Round shows it); maxPath the path
// a hole may return for a stroke (an honest one: a few hundred points).
const (
	maxRoundStrokes = 60
	maxPath         = 512
)

// q4 rounds to the precision a shot is recorded at.
func q4(x float64) float64 { return math.Round(x*1e4) / 1e4 }

// maxTick bounds the third field of a shot: any timed piece turns in fewer.
const maxTick = 1023

// parseShot reads "angle,power" or "angle,power,tick". The tick is where the
// timed pieces were when the player let go (0 if absent), clamped to
// 0..maxTick.
func parseShot(s string) (float64, float64, int) {
	parts := strings.Split(s, ",")
	if len(parts) != 2 && len(parts) != 3 {
		panic(`golf: a shot is "angle,power" or "angle,power,tick", got: ` + s)
	}
	angle, err := strconv.ParseFloat(strings.TrimSpace(parts[0]), 64)
	if err != nil {
		panic("golf: bad angle: " + s)
	}
	power, err := strconv.ParseFloat(strings.TrimSpace(parts[1]), 64)
	if err != nil {
		panic("golf: bad power: " + s)
	}
	tick := 0
	if len(parts) == 3 {
		tick = clampTick(strings.TrimSpace(parts[2]), s)
	}
	return angle, power, tick
}

// clampTick reads a tick: an optional sign and digits, clamped to
// 0..maxTick, even past what an int holds.
func clampTick(t, shot string) int {
	digits := strings.TrimPrefix(strings.TrimPrefix(t, "-"), "+")
	if digits == "" {
		panic("golf: bad tick: " + shot)
	}
	for i := 0; i < len(digits); i++ {
		if digits[i] < '0' || digits[i] > '9' {
			panic("golf: bad tick: " + shot)
		}
	}
	if strings.HasPrefix(t, "-") {
		return 0
	}
	if digits = strings.TrimLeft(digits, "0"); len(digits) > 4 {
		return maxTick
	}
	n, err := strconv.Atoi("0" + digits)
	if err != nil {
		panic("golf: bad tick: " + shot) // digits only, at most 4: cannot happen
	}
	if n > maxTick {
		return maxTick
	}
	return n
}

// roundOf is the player's round under way on e, or a new one from the tee,
// not stored: its commit stores it if it does not finish it.
func roundOf(e *entry, h *course.Simple, player address) *round {
	if v := e.roundTree().Get(player.String()); v != nil {
		return v.(*round)
	}
	s := h.Start()
	return &round{bx: s.X, by: s.Y}
}

// maxName and maxNote bound a hole's name and a version's note.
const (
	maxName = 40
	maxNote = 140
)

// cleanName keeps a hole's name to one short line of plain text
// (cleanText), with at least a letter or a digit in it.
func cleanName(n string) string {
	s := cleanText(n, maxName)
	for _, c := range s {
		if unicode.IsLetter(c) || unicode.IsDigit(c) {
			return s
		}
	}
	return "Untitled hole"
}

// cleanText keeps an author's text to one line of plain text, at most max
// characters: no control, format (Cf: bidi, zero-width, tags) or nonspacing
// (Mn: stacked accents, variation selectors) characters, no blank-looking
// ones, nothing that ends a markdown table cell or opens a link, a tag, an
// HTML entity, a strikethrough, a mention or an email link.
func cleanText(n string, max int) string {
	b := make([]rune, 0, max)
	for _, c := range n {
		if len(b) >= max {
			break
		}
		switch {
		case c < 0x20 || c >= 0x7f && c < 0xa0:
			continue
		case c == 0xad, c == 0x34f, c == 0x61c, c == 0x115f, c == 0x1160, c == 0x17b4, c == 0x17b5, c == 0x180e,
			c >= 0x200b && c <= 0x200f, c >= 0x2028 && c <= 0x202e, c >= 0x2060 && c <= 0x206f,
			c == 0x2800, c == 0x3164, c >= 0xfe00 && c <= 0xfe0f, c == 0xfeff, c == 0xffa0,
			c >= 0xe0000 && c <= 0xe0fff:
			continue
		case unicode.In(c, unicode.Mn, unicode.Cf):
			// é typed as one (NFC) stays; combining marks (Devanagari, Thai) go
			continue
		case !unicode.IsPrint(c) && c != ' ':
			// what Go would print escaped (\U…), which JSON readers refuse
			continue
		case strings.ContainsRune("|[]<>`*_#\\&~@", c):
			continue
		}
		b = append(b, c)
	}
	// no bare link a page might make clickable (": /" keeps the length)
	return strings.TrimSpace(strings.ReplaceAll(string(b), "://", ": /"))
}

// maxSkin bounds a skin's length.
const maxSkin = 24

// cleanSkin keeps a skin to what it is meant to be: a short lower-case id.
func cleanSkin(s string) string {
	b := make([]byte, 0, maxSkin)
	for i := 0; i < len(s) && len(b) < maxSkin; i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == ' ' || c == '-' || c == '_' {
			b = append(b, c)
		}
	}
	return string(b)
}

package golf

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

// The course's owner, the deployer, set at init: golf's only role. Every
// check is on the immediate caller (cur.Previous().Address()), never the
// signer, so a realm the owner calls cannot act in their name. The role
// passes by Transfer then Accept; Renounce freezes the course for good.
var (
	owner   address // "" once renounced
	pending address // the address a Transfer offered the role to, "" if none
)

// self is golf's own pkgpath, hub its gnoweb path: every link follows from
// them, so the same code serves under any namespace.
var (
	self           = unsafe.CurrentRealm().PkgPath()
	hub            = strings.TrimPrefix(self, "gno.land")
	officialPrefix = self[:strings.LastIndex(self, "/")+1] // the namespace's realms, as "…/"
)

// playURL is the 3D client every page links to (SetPlayURL moves it).
var playURL = "https://gnogolf.xyz/"

// successor is the realm that took this course over, "" until the owner
// names it, once (SetSuccessor).
var successor string

func init() { setUp(unsafe.OriginCaller(), runtime.ChainID()) }

// setUp is init: the deployer owns the course, and community publishing
// starts closed. Only `gno test` (chain "dev") runs it with no signer: the
// owner stays "", which holds no power, and publishing starts open, since
// nobody there could open it.
func setUp(deployer address, chainID string) {
	if deployer == "" && chainID != "dev" {
		panic("golf: no owner: golf must be deployed by an account")
	}
	owner, publishing = deployer, deployer == ""
}

// Owner is the course's owner, "" once renounced.
func Owner() address { return owner }

// Pending is the address a Transfer offered the role to, "" if none.
func Pending() address { return pending }

// Successor is the realm that took this course over, "" if none.
func Successor() string { return successor }

// isOwner is the one owner check: a live role, held by the caller.
func isOwner(caller address) bool { return owner != "" && caller == owner }

// Transfer offers the role to another address, which takes it with Accept.
// Offering it to the owner themselves cancels an offer.
func Transfer(cur realm, to address) {
	if !isOwner(cur.Previous().Address()) {
		panic("golf: only the owner can transfer the course")
	}
	if !to.IsValid() {
		panic("golf: not an address: " + to.String())
	}
	if to == owner {
		pending = ""
		chain.Emit(EventOwnershipOfferCancelled, "owner", owner.String())
		return
	}
	pending = to
	chain.Emit(EventOwnershipOffered, "owner", owner.String(), "to", to.String())
}

// Accept takes the role a Transfer offered the caller.
func Accept(cur realm) {
	caller := cur.Previous().Address()
	if owner == "" || pending == "" || caller != pending {
		panic("golf: no transfer of the course is offered to you")
	}
	from := owner
	owner, pending = caller, ""
	chain.Emit(EventOwnershipTransfer, "from", from.String(), "to", owner.String())
}

// Renounce gives the role up for good: no owner, no offer, and none possible.
func Renounce(cur realm) {
	if !isOwner(cur.Previous().Address()) {
		panic("golf: only the owner can renounce the course")
	}
	from := owner
	owner, pending = "", ""
	chain.Emit(EventOwnershipRenounced, "from", from.String())
}

// maxURL bounds the play link, maxPkgPath a successor's pkgpath.
const (
	maxURL     = 100
	maxPkgPath = 100
)

// SetPlayURL moves the link every page gives to the 3D client. Only the
// owner can. url is https://, at most 100 of letters, digits and "-._~/:%",
// with no query or fragment: a hole's link adds "?cup=…&hole=…" to it.
func SetPlayURL(cur realm, url string) {
	if !isOwner(cur.Previous().Address()) {
		panic("golf: only the owner can move the play link")
	}
	if !validURL(url) {
		panic("golf: a play link is https:// and up to 100 of a-z, A-Z, 0-9 and -._~/:%")
	}
	playURL = url
	chain.Emit(EventPlayURLSet, "url", url)
}

func validURL(u string) bool {
	if len(u) > maxURL || !strings.HasPrefix(u, "https://") || len(u) == len("https://") {
		return false
	}
	for i := 0; i < len(u); i++ {
		c := u[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.IndexByte("-._~/:%", c) >= 0) {
			return false
		}
	}
	return true
}

// SetSuccessor names the realm that takes this course over, once and for
// good: a pkgpath under gno.land/r/, not golf itself, with no "", "." or ".."
// segment. Only the owner can. It moves and blocks nothing: the pages and
// Holes say where the course went, and play goes on here. golf does not check
// the realm exists: check the path before sending.
func SetSuccessor(cur realm, pkgpath string) {
	if !isOwner(cur.Previous().Address()) {
		panic("golf: only the owner can name a successor")
	}
	if successor != "" {
		panic("golf: the successor is already " + successor)
	}
	if !validPkgPath(pkgpath) || pkgpath == self {
		panic("golf: a successor is a realm's pkgpath, gno.land/r/ and up to 100 of a-z, 0-9 and _-/.")
	}
	successor = pkgpath
	chain.Emit(EventSuccessorSet, "successor", pkgpath)
}

// Hide takes a community hole ("<address>/<slug>", every version) off the
// lists (the hub, Holes, the 3D game), for a scam or abuse in its name or
// note; hide=false puts it back. Only the owner can. Its data, rounds and
// page stay, Community still has it, and a new version stays hidden. A hole
// already as asked is left alone, with no event.
func Hide(cur realm, slot string, hide bool) {
	if !isOwner(cur.Previous().Address()) {
		panic("golf: only the owner can hide a hole")
	}
	v := aliases.Get(slot)
	if v == nil {
		if e := find(slot); e != nil && !e.official {
			panic("golf: " + slot + " is a version: hide its hole, " + e.slot)
		}
		panic("golf: " + slot + " is not a community hole")
	}
	if hidden.Has(slot) == hide {
		return
	}
	// out of byAuthor, all the lists walk: they never read a hidden hole
	e := find(v.(string))
	a := e.by.String()
	row := a + " " + recentKey(e.height, slot[len(a)+1:])
	was := newestRow(a)
	if hide {
		hidden.Set(slot, true)
		byAuthor.Remove(row)
	} else {
		hidden.Remove(slot)
		byAuthor.Set(row, e.id)
	}
	moveAuthor(a, was, newestRow(a))
	chain.Emit(EventHoleHidden, "slot", slot, "hidden", strconv.FormatBool(hide))
}

// publishing is whether anyone can publish a community hole (PublishMine):
// closed at deploy (setUp), opened later without a redeploy.
var publishing bool

// Publishing is whether PublishMine is open.
func Publishing() bool { return publishing }

// SetPublishing opens community publishing (PublishMine) or closes it again.
// Only the owner can. Closing stops new holes and versions only: every hole
// published stays playable and listed. Setting it as it is does nothing.
func SetPublishing(cur realm, open bool) {
	if !isOwner(cur.Previous().Address()) {
		panic("golf: only the owner can open or close publishing")
	}
	if publishing == open {
		return
	}
	publishing = open
	chain.Emit(EventPublishingSet, "open", strconv.FormatBool(open))
}

func validPkgPath(p string) bool {
	if len(p) > maxPkgPath || !strings.HasPrefix(p, "gno.land/r/") {
		return false
	}
	for _, seg := range strings.Split(p[len("gno.land/r/"):], "/") {
		if seg == "" || seg == "." || seg == ".." {
			return false
		}
	}
	for i := 0; i < len(p); i++ {
		c := p[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || strings.IndexByte("_-/.", c) >= 0) {
			return false
		}
	}
	return true
}

// The events golf emits, and their attributes. A hole is always "hole", a
// player "player".
const (
	EventHolePublished           = "HolePublished"           // hole, slot, sha, by, official ("true"/"false")
	EventHoleRetired             = "HoleRetired"             // hole, next
	EventShot                    = "Shot"                    // hole, player, strokes, mode, shot ("angle,power,tick" as recorded)
	EventHoled                   = "Holed"                   // hole, player, strokes, mode, shots (the round's)
	EventRoundReset              = "RoundReset"              // hole, player
	EventOwnershipOffered        = "OwnershipOffered"        // owner, to
	EventOwnershipOfferCancelled = "OwnershipOfferCancelled" // owner
	EventOwnershipTransfer       = "OwnershipTransfer"       // from, to
	EventOwnershipRenounced      = "OwnershipRenounced"      // from
	EventPlayURLSet              = "PlayURLSet"              // url
	EventSuccessorSet            = "SuccessorSet"            // successor
	EventHoleHidden              = "HoleHidden"              // slot, hidden ("true"/"false")
	EventPublishingSet           = "PublishingSet"           // open ("true"/"false")
)

