// wearRunes draw a cell's wear: none, then up to wearLight, wearWorn and
// wearGroove balls come to rest there, and past.
const (
	wearRunes  = " :;x%" // pristine grass blank: a shot's dots stand out on it
	wearLight  = 2
	wearWorn   = 6
	wearGroove = 14
